export const topics=[];
export const questions=[];
const counters={};
// rows: [题干, 正确项, 三个干扰项, 原创解释, 实际能力层次]
function topic(chapterId,n,title,summary,keyPoints,commonMistake,outlineRef,rows,shortStem,sampleAnswer,extraSources=[],importance='core') {
  const id=`${chapterId}-${String(n).padStart(2,'0')}`;
  topics.push({id,courseId:'15041',chapterId,title,summary,keyPoints,commonMistake,outlineRef,sourceIds:[OUTLINE,...extraSources],level:'understand',importance});
  for(const [stem,correct,a,b,c,explanation,level] of rows){
    const index=counters[chapterId]=(counters[chapterId]||0)+1;
    questions.push({id:`${chapterId}-${String(index).padStart(3,'0')}`,courseId:'15041',chapterId,topicIds:[id],type:'single',stem,options:[correct,a,b,c],answer:0,explanation,level,difficulty:level==='recall'?'basic':level==='apply'?'advanced':'standard',sourceId:OUTLINE,origin:'original',reviewStatus:'checked'});
  }
  const index=counters[chapterId]=(counters[chapterId]||0)+1;
  questions.push({id:`${chapterId}-${String(index).padStart(3,'0')}`,courseId:'15041',chapterId,topicIds:[id],type:'short',stem:shortStem,keyPoints:[...keyPoints],sampleAnswer,explanation:`按设问说明概念与关系；参考要点用于训练自查，不是官方评分细则。易混提醒：${commonMistake}`,level:'understand',difficulty:'standard',sourceId:OUTLINE,origin:'original',reviewStatus:'checked'});
}
function material(chapterId,topicIds,stem,keyPoints,sampleAnswer){questions.push({id:`${chapterId}-material-001`,courseId:'15041',chapterId,topicIds,type:'essay',questionFormat:'material',stem,keyPoints,sampleAnswer,explanation:'材料由本项目原创。先定位历史语境与理论，再逐项分析材料，避免只罗列术语。参考作答供自评，不作为官方评分细则。',level:'apply',difficulty:'advanced',sourceId:OUTLINE,origin:'original',reviewStatus:'checked'});}

topic('mg-intro',1,'理论中国化时代化的提出与必要性','理论要回答中国的问题，必须进入中国的历史条件和人民实践。推进中国化时代化既源于理论发展的要求，也源于解决中国实际问题的需要。',
 ['马克思主义提供认识和改造世界的立场、观点、方法，不是现成方案的汇编。','中国化时代化要求立足中国国情和时代变化，提出能解释和指导实践的新认识。','中国共产党把马克思主义作为指导思想，在实践中不断推进理论创新。'],
 '把学习原理等同于照搬某国在特定条件下采取的措施。','导论/1/识记、领会、应用',[
 ['把一般原理运用于中国具体历史条件并作出理论创造，主要说明什么？','马克思主义中国化时代化','将马克思主义改为一般经验主义','用传统观念替代科学理论','仅将外国著作译成中文','这里强调基本原理同实际结合产生理论发展，不只是语言转换。','recall'],
 ['中国共产党成立之初确立的根本指导思想是','马克思列宁主义','新三民主义','改良主义','无政府主义','指导思想的选择与随后理论中国化的发展应分清，不能把后来的理论名称提前。','recall'],
 ['某研究小组认为“经典著作没有现成答案，研究就没有意义”。较恰当的回应是','运用基本立场和方法研究新问题，在实践中发展认识','只要寻找一句相似论述就能替代调查','研究新问题应先放弃所有基本原理','研究只需列出已有结论而不必解释条件','理论具有方法意义，新的现实问题要求具体分析。','apply'],
 ],'为什么既要学习马克思主义基本原理，又要推进中国化时代化？','基本原理帮助我们把握事物发展的规律，但不能代替对中国国情和时代条件的调查。中国革命、建设、改革面临各自具体任务，需要把普遍原理转化为分析这些问题的理论和方法。实践又会提出新情况，推动理论丰富发展。因此，学习和创新相互支持，既反对照搬书本，也反对脱离基本立场的任意发挥。',['mg-resolution-2021']);

topic('mg-intro',2,'两个结合与科学内涵','两个结合分别指基本原理同中国具体实际、同中华优秀传统文化相结合。结合包含认识实际、解决问题和形成适合中国表达方式的理论创造。',
 ['第一个结合面向中国具体实际，要求具体问题具体分析。','第二个结合面向中华优秀传统文化，以科学态度取其精华、推动转化。','结合形成新的理论认识，不能把原理与材料简单拼接。'],
 '把第二个结合误写为同外国制度、全部传统习俗或抽象中国历史的结合。','导论/2/识记、领会、应用',[
 ['在“两个结合”中，第二个结合明确指向','中华优秀传统文化','中国现有经济总量','外国革命的具体道路','所有历史习俗的原样保留','应把对象表述准确，优秀传统文化与一切旧习俗不能混同。','recall'],
 ['把马克思主义基本原理同中国具体实际相结合，首先要求','研究中国现实条件和具体问题','把外国的政策实施日期照搬过来','依据术语相似程度确定政策','把地域差异视为无需研究的细节','第一个结合重在国情和实践，而非照抄政策。','recall'],
 ['社区借鉴传统民本观念讨论公共服务，同时用现实调查分析居民需要。符合“结合”要求的做法是','辨析传统思想中的合理内容，联系现实需要作创造性转化','把古代管理秩序整体当作现代治理标准','只证明古语与现代术语字面相似','用传统格言代替公共服务效果评价','结合要求辨析、转化并回应现实问题，不能停留在文字对应。','apply'],
 ],'说明两个结合的对象，并以公共服务研究为例解释“结合”为什么不是简单拼接。','第一个结合是基本原理同中国具体实际相结合，第二个结合是同中华优秀传统文化相结合。比如研究养老服务，既要调查本地老龄结构、服务供给和群众需要，也可吸收尊老爱老的文化资源，再形成适合现实的服务方案。把一句古语贴在报告封面上而不改变分析方法，并不等于完成结合。',['mg-resolution-2021']);

topic('mg-intro',3,'历史进程与理论飞跃','理论成果形成于不同历史任务之中。毛泽东思想实现第一次历史性飞跃，中国特色社会主义理论体系在改革开放实践中形成发展，习近平新时代中国特色社会主义思想实现新的飞跃。',
 ['毛泽东思想主要回答中国革命和建设的重大问题。','中国特色社会主义理论体系包括邓小平理论、“三个代表”重要思想、科学发展观和习近平新时代中国特色社会主义思想。','理解飞跃应联系实践任务和理论贡献，不能只按年代排列名称。'],
 '把毛泽东思想列入中国特色社会主义理论体系的内部构成，或把新的飞跃理解为切断理论继承。','导论/3—4/识记、领会、应用',[
 ['马克思主义中国化时代化第一次历史性飞跃的理论成果是','毛泽东思想','邓小平理论','科学发展观','“三个代表”重要思想','第一次飞跃与改革开放后形成的理论成果应区分。','recall'],
 ['下列哪一项属于中国特色社会主义理论体系的组成部分？','邓小平理论','空想社会主义','新三民主义','近代改良主义','中国特色社会主义理论体系在改革开放和现代化建设的实践中形成发展。','recall'],
 ['用“理论飞跃”评价一项成果，最需要说明的是','它在新的历史条件下解决了什么重大问题、作出了什么理论贡献','它比此前著作多使用多少新词','它是否把此前理论的基本立场全部舍弃','它能否取消今后继续探索的必要性','理论飞跃涉及实践基础和认识发展，而不以术语数量判断。','understand'],
 ],'概述毛泽东思想与中国特色社会主义理论体系的关系，说明为何不能混为同一个概念。','二者都坚持马克思主义的立场和方法，具有共同的思想根基。毛泽东思想主要形成于革命与建设实践，是第一次历史性飞跃的理论成果；中国特色社会主义理论体系形成发展于改革开放以来的实践。后者继承前者的科学成果并回答新的时代问题。共同根基说明一脉相承，形成条件和具体内容的差异说明二者不能混同。',['mg-resolution-2021']);

topic('mg-intro',4,'一脉相承又与时俱进','理论成果之间保持基本立场与方法的连续性，同时随着历史任务变化而形成新内容。理解重大时代课题，有助于把握各项成果的区别和联系。',
 ['一脉相承表现为基本立场、根本宗旨和思想方法上的联系。','与时俱进表现为面对新实践提出新观点、回答新课题。','邓小平理论突出回答什么是社会主义、怎样建设社会主义；“三个代表”进一步回答建设什么样的党、怎样建设党；科学发展观回答实现什么样的发展、怎样发展。'],
 '认为继承就是重复结论，或认为创新必须否定所有既有成果。','导论/4/领会、应用',[
 ['“实现什么样的发展、怎样发展”是下列哪一理论着重回答的重大问题？','科学发展观','新民主主义革命理论','农业合作化理论','工农武装割据思想','需按理论着重回答的问题辨识，而非按“发展”一词出现与否判断。','recall'],
 ['“建设什么样的党、怎样建设党”这一重大问题与哪项理论成果直接相关？','“三个代表”重要思想','过渡时期总路线','新民主主义文化纲领','社会主义工业化起步战略','这一时代课题突出执政党建设的新要求。','recall'],
 ['某讲义说“后来的理论研究新问题，所以与此前理论没有联系”。正确的分析是','新课题与基本立场的继承可以同时存在','研究对象变化意味着思想方法必须全部推倒','时间靠后的理论不再需要实践检验','不同历史时期理论只能彼此替代而不能发展','一脉相承和与时俱进是统一关系。','understand'],
 ],'如何理解马克思主义中国化时代化理论成果“一脉相承又与时俱进”？','一脉相承指这些理论坚持共同的基本立场、根本宗旨和科学方法。与时俱进指它们以不同历史阶段的实践为基础，研究革命、建设、改革和发展中的新问题。例如，改革开放需要回答怎样建设社会主义，新的发展阶段又需要研究发展的质量和协调性。这是继承基础上的发展，不是重复旧结论，也不是切断理论联系。',['mg-theory-relations']);

topic('mg-mao',1,'科学内涵与形成发展','毛泽东思想是把马克思列宁主义同中国实际相结合形成的正确理论成果，也是中国共产党集体智慧的结晶。其发展有长期实践基础，不能归结为某个人的所有言论。',
 ['毛泽东思想是被实践证明的关于中国革命和建设的正确理论原则与经验总结。','土地革命战争时期逐步形成，遵义会议以后逐渐成熟，抗日战争时期得到多方面展开。','1945年党的七大将毛泽东思想确立为党的指导思想。','革命和建设的实践、时代条件与党内集体探索共同构成形成发展的基础。'],
 '把毛泽东思想与毛泽东个人一生的全部言论、尤其晚年错误混同。','第一章/1/识记、领会、应用',[
 ['毛泽东思想的科学内涵强调，它是关于中国革命和建设的','被实践证明正确的理论原则和经验总结','个人所有观点不加区分的汇编','脱离社会实践的理论推演','对外国政策文件的逐句解释','正确性和实践检验是科学界定的关键，不等于个人思想的全部。','recall'],
 ['将毛泽东思想确立为党的指导思想的会议是','党的七大','党的二大','党的十一届三中全会','党的十五大','应区分毛泽东思想与邓小平理论写入党章的历史节点。','recall'],
 ['展览把毛泽东思想形成解释为“完全来自一人的书斋思考”。怎样修改更准确？','补充中国革命建设实践和中国共产党集体探索的作用','只增加著作出版的装帧信息','改为所有理论均直接来自外部援助','取消对中国实际历史条件的介绍','理论形成既有主要代表的贡献，也离不开社会实践和集体智慧。','apply'],
 ],'说明毛泽东思想的科学内涵，并概述其形成发展的实践基础。','毛泽东思想是马克思列宁主义在中国的运用和发展，是实践证明正确的中国革命和建设理论原则、经验总结，也是中国共产党集体智慧的结晶。它在土地革命战争中逐步形成，在抗日战争时期多方面展开并走向成熟，后又在革命和建设实践中继续发展。1945年党的七大确立其指导地位。界定时必须把科学理论成果与个人的错误认识区别开。',['mg-resolution-1981']);

topic('mg-mao',2,'科学体系的主要内容','毛泽东思想不仅包含革命道路理论，还涉及社会主义革命建设、人民军队、政策策略、思想文化和党的建设。这些内容由共同的立场观点方法贯通。',
 ['主要内容包括新民主主义革命理论、社会主义革命和建设理论。','还包括革命军队建设和军事战略、政策和策略、思想政治工作和文化工作、党的建设等理论。','人民军队坚持党对军队的领导，重视政治工作和人民战争。','政策和策略要求从实际力量关系出发，把原则性与灵活性结合起来。'],
 '把三大法宝、三大作风、活的灵魂当作可以互换的同一组概念。','第一章/2/识记、领会',[
 ['下列哪项属于毛泽东思想科学体系的内容？','革命军队建设和军事战略的理论','只有农村土地分配的个别技术办法','仅包括抗日战争的战役记录','只涉及革命时期，不涉及建设问题','科学体系涵盖多个相互联系的领域。','recall'],
 ['在毛泽东的建军思想中，人民军队保持性质和方向的重要保证是','坚持党对军队的领导','以军队脱离政治为原则','以临时商业收益决定军队任务','用地方割据取代统一领导','党对军队的领导与军队政治工作相联系。','recall'],
 ['在共同目标不变的前提下，依据不同阶段力量对比调整斗争方式，主要体现','政策策略的原则性与灵活性相结合','以灵活性取消根本目标','用固定战术处理所有阶段','让临时利益替代战略判断','原则规定方向，灵活性回应条件变化，二者不互相排斥。','understand'],
 ],'列举毛泽东思想的主要理论内容，并说明为什么应作为科学体系把握。','其主要内容涉及新民主主义革命、社会主义革命和建设、人民军队与军事战略、政策策略、思想政治与文化工作以及党的建设。这些理论解决不同领域的问题，但都以中国实际为基础，并由实事求是、群众路线、独立自主贯通。把它作为体系理解，才能看到革命任务、领导力量、群众动员和组织建设之间的联系，而不是把若干口号孤立背诵。',['mg-resolution-1981']);

topic('mg-mao',3,'活的灵魂：实事求是、群众路线、独立自主','活的灵魂是贯穿毛泽东思想的立场、观点和方法。实事求是解决怎样认识实际，群众路线说明为了谁、依靠谁以及怎样形成正确领导，独立自主强调立足自身力量。',
 ['实事求是要求从客观实际出发，研究规律，用实践检验和发展认识。','群众路线是为群众、靠群众，从群众中集中意见并回到群众实践中去。','独立自主要求自己思考、立足本国实际和自身力量，也积极学习外部有益经验。'],
 '把群众路线理解为照办所有个人意见，把独立自主理解为拒绝交流。','第一章/2/识记、领会、应用',[
 ['毛泽东思想活的灵魂的三个基本方面是','实事求是、群众路线、独立自主','统一战线、武装斗争、党的建设','土地革命、武装斗争、根据地建设','理论联系实际、密切联系群众、批评与自我批评','四组概念分别有特定所指，活的灵魂是立场观点方法。','recall'],
 ['群众路线中“从群众中来，到群众中去”强调的领导方法是','集中群众经验形成认识，再到群众实践中贯彻检验','把各人互相冲突的意见不加分析地全部执行','仅向群众宣布已作好的决定','以少数人的主观设想替代群众实践','群众路线包含调查、集中、实践和检验的过程。','understand'],
 ['某地学习外地治理经验前先调查本地人口和产业条件，并试点后调整方案。这主要体现','实事求是与独立自主可以同学习借鉴相统一','独立自主要求拒绝全部外来经验','学习借鉴意味着必须采用原方案所有细节','有了典型经验就无需实践检验','自主判断和吸收有益经验并不矛盾。','apply'],
 ],'说明活的灵魂三个方面的内涵，并用调查研究的例子说明其联系。','实事求是要求按照客观实际和规律办事；群众路线要求为了群众、依靠群众，并把分散经验集中后再用于群众实践；独立自主要求立足本国实际与自身力量作出判断。比如改善农村供水，先入户听取需求，核对水源和资金条件，再提出方案并试行反馈。这同时体现实际分析、群众参与和自主决策，而不是照抄外地方案。',['mg-resolution-1981']);

topic('mg-mao',4,'历史地位与科学评价','毛泽东思想是马克思主义中国化时代化第一个重大理论成果，是中国革命和建设的科学指南，也是需要长期珍视的精神财富。坚持科学评价，既不抹去贡献，也不把错误当作理论正确部分。',
 ['第一次历史性飞跃的理论成果，丰富和发展了马克思主义。','指导中国革命取得胜利，并指导社会主义革命和建设。','其中科学立场方法对后来中国特色社会主义事业具有重要指导意义。','评价历史人物、科学理论与具体政策，应区分对象和条件。'],
 '因发生过曲折就全盘否定科学理论，或因肯定历史贡献就拒绝总结错误。','第一章/3/识记、领会、应用',[
 ['从理论发展角度看，毛泽东思想的历史地位是','马克思主义中国化时代化第一个重大理论成果','中国特色社会主义理论体系的开篇之作','社会主义市场经济体制的具体实施方案','新时代全部具体政策的直接清单','开篇之作通常用于邓小平理论在中国特色社会主义理论体系中的地位。','recall'],
 ['对毛泽东思想作科学评价，应当区分','经过实践检验的科学成果与个人晚年错误','军事理论与所有社会实践的联系','历史贡献与当时任何政策的相同效力','理论原则与政治评价之间完全无关的关系','把科学理论同个人所有言论混同会同时损害肯定和批评的准确性。','understand'],
 ['学生说“既然建设中有过失误，实事求是等方法就没有学习价值”。合理回应是','应具体分析失误与科学方法的关系，不能据局部错误否定整个理论成果','只要肯定历史贡献就不应研究失误','历史人物的每一句话都具有相同理论效力','对失误的认识可代替对理论内容的学习','科学评价要求把贡献、错误、理论和实践条件具体区分。','apply'],
 ],'简述毛泽东思想的历史地位，并说明如何把坚持与科学评价统一起来。','毛泽东思想实现马克思主义中国化时代化的第一次历史性飞跃，指导中国革命和建设，是党和人民的重要精神财富。坚持它，主要是坚持其中科学的理论原则、立场和方法。科学评价同时要求正视历史曲折，把正确理论与错误认识区分开，在总结经验教训中发展认识。肯定贡献与研究错误并不矛盾。',['mg-resolution-1981','mg-resolution-2021']);

topic('mg-revolution',1,'近代国情、主要矛盾与革命任务','近代中国的半殖民地半封建社会性质决定了革命面对的基本问题。民族独立、人民解放和国家富强、人民幸福两大历史任务相互联系，又有实现上的先后条件。',
 ['近代中国社会性质是半殖民地半封建社会。','主要矛盾包括帝国主义同中华民族、封建主义同人民大众的矛盾，前者是最主要的矛盾。','民族独立和人民解放为实现国家富强、人民幸福创造前提。','五四运动标志中国新民主主义革命的开端。'],
 '把半殖民地理解为中国已完全成为某一殖民国家，或认为两大历史任务互不相关。','第二章/1/识记、领会',[
 ['判断近代中国革命性质和任务的基本依据是','半殖民地半封建的社会性质','中国已有成熟的社会主义经济','中国完全不存在资本主义经济','所有地区发展状况完全相同','革命性质首先要从社会性质和主要矛盾分析。','recall'],
 ['中国新民主主义革命的开端通常以哪一事件为标志？','五四运动','洋务运动开始','中华人民共和国成立','社会主义改造基本完成','五四运动与中国工人阶级以独立政治力量登上历史舞台相联系。','recall'],
 ['分析近代两大历史任务时，正确的关系判断是','民族独立、人民解放为国家富强、人民幸福创造前提','发展经济可以自动消除外来侵略和封建统治','两大任务在内容上完全相同','先实现现代化才能开始争取民族独立','应理解革命与发展的联系和历史条件。','understand'],
 ],'从近代中国国情说明新民主主义革命为什么首先承担反帝反封建任务。','半殖民地半封建的社会性质使外来帝国主义侵略和国内封建统治成为民族独立、人民解放的重要障碍。近代中国的主要矛盾规定了革命的基本对象和任务。必须争取民族独立、人民解放，才能为国家富强、人民幸福创造条件。因此，不能脱离国情把当时民主革命直接解释为消灭一切私有经济的社会主义革命。',['mg-resolution-2021']);

topic('mg-revolution',2,'总路线：领导、动力、对象与前途','新民主主义革命由无产阶级领导，人民大众参加，反对帝国主义、封建主义和官僚资本主义。领导力量和革命前途使其区别于旧民主主义革命，但其当时的社会性质仍是民主主义革命。',
 ['革命对象为帝国主义、封建主义和官僚资本主义。','动力包括工人、农民、城市小资产阶级和民族资产阶级；农民是主力军。','无产阶级及其政党的领导是新旧民主主义革命区别的根本标志。','革命性质是新式资产阶级民主主义革命，前途是社会主义；民主革命是社会主义革命的必要准备。'],
 '把官僚资本主义和民族资本主义混同，或把社会主义前途写成当时已是社会主义革命。','第二章/2/识记、领会、应用',[
 ['区分新旧民主主义革命的根本标志是','领导权掌握在无产阶级还是资产阶级手中','是否存在农民参加','是否反对民族压迫','是否提出改善民生的要求','许多任务和参与者可有相似之处，领导权是根本区别。','recall'],
 ['在新民主主义革命动力中，作为主力军的是','农民阶级','官僚资产阶级','地主阶级','帝国主义在华代理人','农民人口比重和所受压迫使其成为重要革命力量；领导力量则是工人阶级。','recall'],
 ['某讲解称“革命前途是社会主义，因此当时应立即没收全部民族工商业”。正确判断是','混淆了民主革命的当前任务与社会主义革命的后续任务','只要有社会主义前途就不存在民主革命阶段','民族资产阶级始终属于官僚资产阶级','革命前途与革命性质在任何阶段必须用同一术语','反官僚资本与保护民族工商业有明确对象区别。','apply'],
 ],'说明新民主主义革命的性质、领导力量和前途，并解释它同社会主义革命的联系。','新民主主义革命由无产阶级领导，反对帝国主义、封建主义和官僚资本主义，性质仍是新式资产阶级民主主义革命。它的前途是社会主义。民主革命为社会主义革命准备政治经济条件，社会主义革命则是民主革命的必然发展。二者既相衔接又任务不同，所以不能在民主革命阶段不分对象地消灭全部私人资本。',['mg-resolution-1981']);

topic('mg-revolution',3,'政治、经济、文化基本纲领','新民主主义基本纲领从国家政权、经济关系和文化方向体现总路线。经济纲领区分地主土地、官僚资本和民族工商业，不能把不同对象采用同一处理办法。',
 ['政治上建立无产阶级领导、以工农联盟为基础、各革命阶级联合专政的新民主主义共和国，采取民主集中制的人民代表大会制度。','经济上没收地主土地归农民所有，没收官僚资本归新民主主义国家所有，保护民族工商业。','文化上发展无产阶级领导的民族的、科学的、大众的文化。','1948年土地改革总路线强调依靠贫农、团结中农，逐步消灭封建剥削制度，发展农业生产。'],
 '把保护民族工商业误写为维护官僚资本，或把民族文化理解为排斥科学交流。','第二章/2/识记、领会',[
 ['新民主主义经济纲领对民族工商业的基本政策是','保护','作为官僚资本一并无偿没收','以恢复地主土地所有制为条件予以保留','立即全部改为农业合作社','处理官僚资本与民族资本的政策不同，源于其经济政治性质的不同。','recall'],
 ['新民主主义文化的概括是','民族的、科学的、大众的文化','以复古为目的的宗法文化','脱离人民生活的少数人文化','否定民族形式的纯技术文化','三个方面分别体现民族立场、科学态度和服务人民的方向。','recall'],
 ['设计新民主主义经济纲领图表，哪种对应关系正确？','地主土地归农民，官僚资本归新民主主义国家，民族工商业受保护','地主土地归旧政府，民族工商业一律没收','官僚资本交给地主，农民土地收归私人财团','三种经济对象都按同一方式分给个人','基本纲领强调区分对象和阶级关系。','understand'],
 ],'分别概括新民主主义政治、经济、文化纲领，并说明经济纲领中的对象区分。','政治纲领旨在建立由无产阶级领导、以工农联盟为基础的各革命阶级联合专政。经济纲领是地主土地归农民、官僚资本归新民主主义国家，并保护民族工商业。文化纲领是发展民族的、科学的、大众的文化。经济上采取不同政策，是因为封建土地关系、官僚资本与民族资本的性质及作用不同，不能只因都含私人财产就作相同处理。',['mg-resolution-1981']);

topic('mg-revolution',4,'农村包围城市与工农武装割据','中国革命道路是依据敌强我弱、农村人口众多、发展不平衡等条件探索出来的。土地革命、武装斗争和根据地建设相互依存，形成工农武装割据的整体。',
 ['农村包围城市、武装夺取政权不是照搬外国城市起义模式。','土地革命是民主革命的基本内容，武装斗争是主要形式，根据地是战略阵地。','道路形成的条件包括政治经济发展不平衡、农村群众基础、革命力量及党的正确领导。','坚持道路创新不等于否认城市工作的地位。'],
 '只谈农村地域，不说明土地、武装与根据地三者的结合；把道路理解为永久放弃城市。','第二章/3/识记、领会、应用',[
 ['“工农武装割据”思想把哪三方面联系起来？','土地革命、武装斗争、农村革命根据地建设','统一战线、批评、自我批评','工业、农业、国防现代化','和平共处、贸易、外交谈判','应区分道路建设的三个方面与三大法宝。','recall'],
 ['在工农武装割据的构成中，农村革命根据地的主要作用是','提供开展革命斗争的战略阵地','取代一切群众工作','证明城市工作毫无作用','使武装斗争脱离经济社会基础','根据地能把政权、经济和群众动员联系起来。','understand'],
 ['某小组解释革命道路，只说“农村面积大”。还应补充的关键分析是','社会矛盾、敌我力量分布、群众基础及党的领导等具体条件','把道路选择仅归因于地图比例','以任何国家都相同的地理定律替代国情分析','认为道路与群众的土地要求无关','道路形成需要综合历史条件，地理现象不足以独立解释。','apply'],
 ],'说明土地革命、武装斗争和根据地建设的关系，以及这条道路体现的方法。','土地革命回应农民的土地要求，是民主革命的重要内容；武装斗争为革命提供主要斗争形式；根据地是组织生产、政权和群众工作的战略阵地。三者相互依存，不能分割。农村包围城市的道路体现从中国社会性质、群众基础和力量对比出发探索道路的方法，而不是把某种外国经验当作固定模板。',['mg-resolution-2021']);

topic('mg-revolution',5,'三大法宝、统一战线与党的建设','统一战线团结可团结的力量，武装斗争维护和发展革命力量，党的建设保证领导方向。三者相互联系，统一战线中的联盟关系也要坚持无产阶级的领导。',
 ['三大法宝是统一战线、武装斗争、党的建设。','统一战线包含以工农联盟为主体的劳动者联盟，以及同非劳动者的联盟；前者是基础。','统一战线既有联合又有斗争，应坚持独立自主和党的领导。','党的建设重视思想建设，并形成理论联系实际、密切联系群众、批评与自我批评三大优良作风。'],
 '把统一战线理解为放弃独立自主，把武装斗争理解为不需要政治领导。','第二章/3/识记、领会、应用',[
 ['新民主主义革命三大法宝中，保证革命领导力量建设的是','党的建设','土地平均分配','现代企业制度','外交中立政策','党的建设与统一战线、武装斗争共同构成三大法宝。','recall'],
 ['新民主主义革命统一战线的基础是','工人阶级同农民及其他劳动者的联盟','工人阶级同官僚资产阶级的联盟','地主阶级与外国侵略势力的联合','所有政治力量不分目标的联合','劳动者联盟是基础，非劳动者联盟具有不同地位。','recall'],
 ['革命统一战线中，为扩大联合而取消党的独立主张，符合其经验吗？','不符合，团结合作要同坚持领导权和独立自主相结合','符合，联合范围越广越无需组织领导','符合，有共同目标就不再存在利益差异','不符合，因为统一战线要求拒绝所有阶级外合作','联合和斗争须根据共同目标与现实差异把握，不能走向两个极端。','understand'],
 ],'解释三大法宝的相互关系，并说明统一战线为什么需要坚持党的建设。','统一战线解决团结力量问题，武装斗争是中国革命的主要斗争形式，党的建设使党能够正确运用前两个武器并保持领导方向。统一战线中既有共同利益，也有不同阶级的差异，必须坚持独立自主和领导权。党的思想、政治和组织建设以及优良作风，使党能够联系群众、制定策略并开展合作，而不是在联合中失去自身方向。',['mg-resolution-1981']);

topic('mg-transition',1,'新民主主义社会的过渡性质','新中国成立后到社会主义改造基本完成，是由新民主主义向社会主义转变的时期。社会中存在多种经济成分，社会主义经济具有领导地位，而不是资本主义经济单独主导的发展阶段。',
 ['新民主主义社会具有过渡性质，指向社会主义社会。','存在国营、合作社、个体、私人资本主义和国家资本主义五种经济成分。','主要经济成分是社会主义经济、个体经济和资本主义经济；个体经济具有向不同方向发展的可能。','土地改革基本完成后，工人阶级与资产阶级的矛盾成为国内主要矛盾。'],
 '把过渡社会当成可无限延长的独立社会形态，把个体经济直接等同于资本主义经济。','第三章/1/识记、领会',[
 ['新民主主义社会在历史发展中的性质是','向社会主义转变的过渡性社会','已经完成现代化的社会主义社会','资本主义经济取得唯一地位的社会','封建土地关系全面恢复的社会','过渡性质与经济成分并存相联系，不能从多种成分推出资本主义主导。','recall'],
 ['在新民主主义社会五种经济成分中，具有社会主义性质并居领导地位的是','国营经济','私人资本主义经济','个体小农经济','完全由私人资本控制的商业','国营经济的领导地位是向社会主义过渡的重要经济条件。','recall'],
 ['看到当时存在私人资本主义经济，就认定新民主主义社会必然长期走资本主义道路，这种推论','忽视了社会主义经济的领导地位与整个社会的过渡方向','正确揭示了全部经济成分具有相同性质','说明当时不存在工人阶级政权','说明经济成分的数量可直接决定社会前途','判断社会方向要分析领导力量、经济结构和历史任务。','understand'],
 ],'说明新民主主义社会的性质和主要经济成分，为什么不能把它简单称为资本主义社会？','新民主主义社会是向社会主义过渡的社会，存在五种经济成分，其中社会主义、个体和资本主义经济是主要成分。社会主义国营经济处于领导地位，人民政权掌握关键经济力量，具有向社会主义转变的条件。因存在私人资本就把整个社会等同于资本主义社会，忽略了领导地位、政权性质和发展方向。',['mg-transition-history']);

topic('mg-transition',2,'过渡时期总路线：一化三改','党在过渡时期把工业化与所有制改造结合起来。工业化发展生产力，改造逐步调整生产关系，二者相互促进，而不是先后完全隔离的两段任务。',
 ['过渡时期从中华人民共和国成立到社会主义改造基本完成。','总路线的主体是社会主义工业化，两翼是对农业、手工业和资本主义工商业的社会主义改造。','工业化建设与社会主义改造同时并举，体现发展生产力与变革生产关系的联系。','国营经济的发展、工业化的需要、社会主义改造的有利条件和相对稳定的环境，是总路线提出的重要现实依据。'],
 '将“一化”误写为农业现代化，或把“三改”理解为三个互不相关的技术改革。','第三章/1/领会、应用',[
 ['过渡时期总路线中“一化”的主体内容是','社会主义工业化','城市绿化','农业全面机械化','对外贸易自由化','工业化是主体，三大改造是相联系的任务。','recall'],
 ['“一化三改”中的“三改”是对哪些领域的社会主义改造？','农业、手工业、资本主义工商业','科技、教育、国防','城市、乡村、边疆','金融、交通、外交','这里按所有制改造对象划分，不能同现代化的领域划分混同。','recall'],
 ['讨论工业化与改造的关系，符合过渡时期总路线的是','建设和改造并举，使生产关系调整同生产力发展相适应','工业化完成之前不得进行任何所有制调整','所有制改变后不再需要发展生产力','只改变产权称谓就等于完成工业化','总路线体现建设与改造的相互支持，不能以一方替代另一方。','understand'],
 ],'说明过渡时期总路线的主要内容及工业化与社会主义改造的关系。','总路线要求逐步实现社会主义工业化，并逐步完成对农业、手工业和资本主义工商业的社会主义改造，通常概括为一化三改。工业化发展生产力并为改造提供物质条件，改造调整生产关系，为工业化创造制度和组织条件。二者同时并举、相互促进。分析时既不能只讲制度变化而忽略生产，也不能把改造无限推迟到工业化完全结束以后。',['mg-transition-line']);

topic('mg-transition',3,'农业与手工业合作化道路','合作化把分散的小生产者逐步组织起来。农业改造强调自愿互利、典型示范和国家帮助，采取由互助到合作、由低级到高级的过渡形式。',
 ['农业合作化遵循自愿互利、典型示范和国家帮助等原则。','主要经过互助组、初级农业生产合作社和高级农业生产合作社。','互助组具有社会主义萌芽，初级社为半社会主义性质，高级社具有完全社会主义性质。','手工业一般经过生产合作小组、供销生产合作社和生产合作社等形式，注意适合行业特点。'],
 '把互助组当成已实现土地集体所有的高级社，或把合作化原则理解为以行政强迫代替自愿。','第三章/2/识记、领会',[
 ['农业社会主义改造由低级到高级的主要组织形式依次是','互助组、初级社、高级社','高级社、互助组、初级社','公私合营、合作小组、私营独资','家庭承包、股份公司、国家资本主义','形式变化体现组织程度和社会主义因素的逐步增加。','recall'],
 ['初级农业生产合作社的性质通常概括为','半社会主义性质','完全社会主义性质','官僚资本主义性质','封建庄园性质','初级社与高级社的性质不能混同。','recall'],
 ['分析农业合作化历史经验时，把强制入社作为自愿互利的替代，正确评价是','不符合原则，组织形式和推进步骤应尊重群众意愿与实际条件','符合原则，只要形式统一就自然提高生产','符合原则，自愿只适用于资本主义工商业','不符合原则，因为任何形式的互助都不能有国家帮助','合作化原则同时包含群众自愿、互利和国家支持。','apply'],
 ],'概述农业合作化的主要步骤和原则，并说明为什么应由低级向高级推进。','农业合作化主要经过互助组、初级社和高级社，社会主义因素逐步增加。推进中应坚持自愿互利、典型示范和国家帮助。低级形式有助于积累经营和组织经验，逐步提高生产者接受程度，并为更高程度合作创造条件。不能把改造理解为只更换组织名称，更不能用强迫代替群众自愿和实际成效。',['mg-transition-history']);

topic('mg-transition',4,'和平赎买与社会主义基本制度确立','对资本主义工商业的改造采取和平赎买，通过国家资本主义形式逐步过渡。1956年底三大改造基本完成，标志社会主义基本制度在我国确立。',
 ['和平赎买通过有偿方式逐步将资本主义私有制转变为社会主义公有制。','初级国家资本主义形式包括加工订货、统购包销等，高级形式主要是公私合营。','“四马分肥”涉及国家税收、企业公积金、工人福利费和资本家红利，不等于全部利润归资本家。','改造同生产发展、人员安排相结合，并在基本完成后形成以公有制为基础的社会主义经济制度；也应总结后期推进过快等不足。'],
 '把和平赎买解释为保留资本主义所有制不变，或把国家资本主义误认为社会主义国营经济的同义词。','第三章/2—3/识记、领会、应用',[
 ['资本主义工商业社会主义改造采取的主要政策是','和平赎买','对一切工商业无偿没收','恢复官僚资本控制','只降低税率而不改变所有制','和平赎买以逐步改变所有制为方向，不是单纯税收优惠。','recall'],
 ['社会主义基本制度在中国确立的重要标志是','1956年底社会主义改造基本完成','五四运动发生','新民主主义革命理论开始形成','1978年改革开放启动','应区分建国、改造完成和改革开放三个节点。','recall'],
 ['把公私合营解释为“国家只提供订单，企业所有制完全不变”，主要需要澄清','公私合营属于高级国家资本主义，是逐步改变资本主义所有制的过渡形式','只要国家参与，企业就永远不能改变性质','加工订货与全行业公私合营完全相同','和平赎买的目标是使私人资本永久取得领导地位','不同形式的改造程度不同，不能用初级形式替代高级形式。','understand'],
 ],'解释和平赎买及其过渡形式，并说明三大改造基本完成的意义。','和平赎买是以有偿方式逐步改变资本主义所有制。国家先通过加工订货等初级国家资本主义形式加强联系，再经公私合营等高级形式完成过渡，并重视生产与人员安排。1956年底三大改造基本完成，社会主义基本制度确立，为工业化和以后的发展提供制度基础。评价时既应肯定制度变革，也要总结推进过快、形式过于单一等经验教训。',['mg-transition-history']);

topic('mg-exploration',1,'第二次结合与调动积极因素','社会主义制度建立后，党以苏联经验教训为借鉴，探索适合中国的建设道路。《论十大关系》围绕调动积极因素，从中国实际分析经济和政治关系。',
 ['这里的“第二次结合”指把马克思列宁主义基本原理同中国实际再次结合，探索社会主义建设道路。','它不同于“两个结合”中同中华优秀传统文化相结合的“第二个结合”。','《论十大关系》强调调动国内外一切积极因素为社会主义事业服务，第一大关系是重工业和轻工业、农业的关系。','调动积极因素要坚持党的领导、发展社会主义民主政治，分析积极与消极因素的转化。'],
 '把20世纪50年代的“第二次结合”同新时代“第二个结合”当成同一概念。','第四章/1/识记、领会',[
 ['社会主义建设探索语境中的“第二次结合”，着重指','以中国实际为基础探索自己的社会主义建设道路','只把中国传统典籍逐句译为马克思主义术语','对苏联全部政策不作区分地复制','停止用马克思主义研究经济建设','历史语境决定概念含义，不能与“第二个结合”混同。','recall'],
 ['《论十大关系》讨论的第一大关系是','重工业和轻工业、农业的关系','国民收入与个人所得税税率的关系','城市金融与国际汇率的关系','公私合营与定息支付的关系','第一大关系体现对工业化比例和基础条件的重视。','recall'],
 ['某总结将学习苏联理解为“沿用其所有建设比例，无需比较国情”。结合初步探索，应当主张','借鉴经验教训，通过调查形成适合中国实际的建设安排','只要来源于社会主义国家就无需检验','只依据对外国经验的好恶决定政策','既然强调自主，就应停止一切国际学习','初步探索旨在反对机械照搬而非拒绝借鉴。','apply'],
 ],'说明建设道路探索中“第二次结合”的含义，并与“第二个结合”作出区分。','建设探索中的第二次结合，是以苏联经验教训为借鉴，把马克思列宁主义基本原理同中国实际相结合，探索适合中国的社会主义建设道路。它回应的是制度确立后的建设任务。两个结合中的第二个结合则明确指基本原理同中华优秀传统文化相结合。二者都体现理论联系实际，但概念对象和提出语境不同，不能互换。',['mg-resolution-2021']);

topic('mg-exploration',2,'社会主义社会矛盾与人民内部矛盾','社会主义社会仍存在生产力与生产关系、经济基础与上层建筑的基本矛盾。区分敌我矛盾和人民内部矛盾的性质，有助于采用不同的处理方法。',
 ['社会主义社会基本矛盾不是消失了，而是能通过社会主义制度自身调整解决。','敌我矛盾与人民内部矛盾性质不同，处理方法不能混用。','人民内部矛盾一般用民主方法解决，政治思想领域采用团结—批评—团结的方针。','科学文化领域实行百花齐放、百家争鸣；处理经济等领域关系应统筹兼顾、适当安排。'],
 '把一切意见分歧视为敌我矛盾，或把社会主义制度确立理解为社会不再有矛盾。','第四章/1/识记、领会、应用',[
 ['社会主义社会的基本矛盾仍然是','生产力与生产关系、经济基础与上层建筑的矛盾','只存在个人情绪与组织纪律的矛盾','只存在对外贸易顺差与逆差的矛盾','抽象的东方文化与西方文化的矛盾','基本矛盾涉及社会结构，不能缩小为某个领域的具体冲突。','recall'],
 ['解决人民内部政治思想方面矛盾的具体方针是','团结—批评—团结','对所有分歧采取专政方法','用行政命令裁决全部学术问题','把意见差异永久固定为敌我界限','其出发点和归宿是团结，通过批评解决问题。','recall'],
 ['讨论建设方案时，有人把善意批评直接等同于敌对行为。按两类矛盾理论，更合适的处理是','先分析矛盾性质，对人民内部意见分歧采用民主讨论等方法','以是否提出不同意见作为唯一敌我标准','把所有批评都免于事实核验','用一次表决取消以后继续讨论的可能','区分性质是选择处理方法的前提，不能把分歧一概敌对化。','apply'],
 ],'说明两类社会矛盾的区别，以及正确处理人民内部矛盾的基本思路。','敌我矛盾与人民内部矛盾性质不同，通常分别采用专政与民主的方法，不能混同。人民内部矛盾的处理要从团结愿望出发，通过讨论、批评和教育解决问题，在新的基础上达到团结。不同领域还应有具体方针，如科学文化上的双百方针。关键是先分析实际矛盾的性质和条件，而不是见到批评就作敌我定性。',['mg-resolution-1981']);

topic('mg-exploration',3,'工业化道路与经济关系调整','中国工业化探索重视农业和轻工业对重工业的支持，并关注所有制形式、市场补充和利益关系。工业化不能只理解为重工业投资越集中越好。',
 ['重视重工业的同时，应发展农业和轻工业，为工业化提供粮食、原料、市场和积累。','处理国家、集体和个人之间以及中央和地方的关系，要兼顾需要、调动积极性。','陈云提出“三个主体、三个补充”，分别涉及经营、生产和市场关系，在主体地位下保留一定补充形式。','探索应尊重经济规律，综合平衡规模、速度、比例和群众生活。'],
 '把重工业优先发展误解为农业、轻工业可以不发展，或把市场补充误写为完全取消计划。','第四章/1/领会、应用',[
 ['初步探索认为农业和轻工业对工业化的重要作用包括','提供粮食、原料、市场和积累','使重工业从此不再需要发展','代替所有国防与基础工业','仅用于决定城市名称和行政区划','农业、轻工业与重工业之间存在经济联系。','recall'],
 ['“三个主体、三个补充”思想主要探索的是','主体经济形式与必要补充形式的合理关系','以外国资本替代国营经济','立即取消社会主义公有制','用纯粹指令分配排除一切补充形式','这一探索承认主体下的补充，有别于单一僵化形式。','recall'],
 ['某历史工业化方案把全部积累投向重工业，导致农业与消费品供给被长期忽视。应从哪方面检视？','农轻重比例、生产积累与群众生活的相互关系','只比较重工业厂房的建筑面积','以投资越集中越先进作唯一评价','认为消费品短缺与工业化没有关联','要综合分析工业化的资源、市场和社会条件。','apply'],
 ],'为什么中国工业化道路探索强调正确处理农轻重关系？','农业提供粮食和原料，轻工业提供消费品并较快形成积累，重工业提供技术装备。三者相互支持。只强调重工业而长期忽略农业和轻工业，会影响原料、市场、人民生活和继续积累。探索因此要求在重视重工业的同时协调比例，并处理国家、集体、个人及中央地方的利益关系，以调动各方面积极性。',['mg-resolution-1981']);

topic('mg-exploration',4,'现代化目标、科学文化与三线建设','初步探索不仅涉及经济比例，也涉及现代化目标、科学文化政策和国家建设布局。这些探索需要放在当时发展基础和安全环境中理解。',
 ['四个现代化是农业、工业、国防、科学技术现代化；相关战略强调逐步建设独立、比较完整的工业和国民经济体系。','科学文化工作提出百花齐放、百家争鸣，重视知识分子的作用。','三线建设从经济建设和国防建设布局出发，加强内地工业、交通和科研等基础。','这些历史探索应结合时代条件评价，不可直接当成今天一切地区的固定方案。'],
 '把“四个现代化”的构成与“三个面向”混同，把“三线”理解为三条单独铁路。','第四章/1/识记、领会',[
 ['四个现代化的完整领域组合是','农业、工业、国防和科学技术','经济、政治、文化和外交','农业、金融、旅游和交通','民主、法治、自由和平等','四个现代化是特定的历史战略概念，不同于其他总体布局。','recall'],
 ['“百花齐放、百家争鸣”主要针对的领域是','科学与文化','关税税率与汇率','农业税制和土地登记','私人资本红利分配','双百方针与处理科学文化领域问题相联系。','recall'],
 ['解说三线建设时，最贴近其历史背景的表述是','兼顾经济与国防布局，增强内地工业和相关基础能力','因有三条铁路而把全国经济分为三个行业','以取消全部沿海工业为目标','以短期旅游开发替代工业基础建设','三线建设与国家工业布局和安全考虑有关，不能仅按字面解释。','understand'],
 ],'列举初步探索中现代化、科学文化和建设布局方面的成果，并说明评价时应注意什么。','相关探索提出农业、工业、国防和科学技术现代化的目标，重视建立独立、比较完整的工业体系；科学文化工作提出双百方针，重视知识分子作用；三线建设加强了内地工业及交通科研基础。评价时应联系当时的工业基础、发展需要和安全环境，既看到成就，也分析布局和资源使用中的不足，不能把历史方案不加调整地套用于今天。',['mg-resolution-2021']);

topic('mg-exploration',5,'初步探索的意义与经验教训','初步探索取得独创性理论成果和建设成就，也经历严重曲折。科学总结应同时把握贡献与教训，理解它同改革开放以后实践的历史联系。',
 ['探索巩固发展了社会主义制度，形成工业与国民经济基础，提高独立发展能力。','为后来的中国特色社会主义提供宝贵经验、理论准备和物质基础。','经验教训包括正确认识主要矛盾和根本任务、尊重经济规律、从国情出发、发扬民主与加强制度建设。','既不能以成就掩盖失误，也不能以失误抹去全部探索成果。'],
 '把改革开放前后两个历史时期割裂，或只用单项指标作全盘肯定或否定。','第四章/2/识记、领会、应用',[
 ['初步探索为后来开创中国特色社会主义提供的重要条件可概括为','宝贵经验、理论准备和物质基础','一套无需调整的永久固定政策','已经完成全部现代化的社会条件','不再需要任何制度改革的经济体系','历史基础与后来继续改革创新并不冲突。','recall'],
 ['总结建设探索的教训，符合实事求是的是','尊重客观经济规律，使建设安排符合国情和发展阶段','以愿望强弱替代生产条件分析','把群众积极性等同于可取消一切资源约束','只要目标正确就不必评价实施方法','目标、条件、方法与效果都需要分析。','understand'],
 ['某展览既列出工业体系建设成就，也介绍探索中的严重曲折。组织说明应采用','具体分析成就、失误及其条件，说明经验如何服务后续发展','为突出成就而删去一切失误资料','因存在失误而撤销全部建设成就介绍','把不同历史阶段认定为完全无关','历史评价应全面、具体，避免片面化。','apply'],
 ],'概括初步探索的意义，并说明怎样从教训中理解后来的改革。','初步探索巩固了社会主义制度，建立起重要工业和国民经济基础，积累了独立建设经验，为中国特色社会主义提供理论准备和物质条件。曲折也说明建设必须尊重国情、发展阶段和经济规律，并健全民主法制、改善领导方法。改革是继承基础上的自我完善，既不是证明过去毫无价值，也不是照搬过去的一切安排。',['mg-resolution-2021']);

topic('mg-system',1,'理论体系形成发展的社会历史条件','中国特色社会主义理论体系形成于时代条件变化和中国改革开放实践。分析其历史条件，要把国际环境、国内任务以及党自身面临的课题联系起来。',
 ['和平与发展成为时代主题，世界开放和相互联系加深，为集中力量发展提供可能。','中国的发展离不开世界，需要在独立自主基础上实行开放。','改革开放和现代化建设的实践提出新的问题，推动理论发展。','党必须提高领导水平和执政水平，提高拒腐防变和抵御风险能力。'],
 '把和平与发展作为时代主题误解为世界从此不存在战争或风险。','第五章/1/识记、领会',[
 ['改革开放新时期对时代主题的基本判断是','和平与发展','战争与革命是唯一的现实主题','世界各国不再有任何利益差异','全球发展已完全均衡','时代主题是总体判断，并不表示局部冲突和发展问题消失。','recall'],
 ['党面临的两大历史性课题之一是','提高拒腐防变和抵御风险的能力','把经济建设从党和国家任务中取消','以组织数量代替执政能力','消除社会分工带来的全部差别','另一课题是提高领导水平和执政水平。','recall'],
 ['有人以某地仍存在战争为由，否定和平与发展时代主题的判断。正确分析是','时代主题反映主要趋势和任务，不等于每个地区都无冲突','只要有冲突就不能再开展任何经济合作','时代主题只取决于某一国家的政策名称','和平主题意味着国防建设已无必要','要区分总体时代判断与具体矛盾的存在。','understand'],
 ],'从国际环境和国内实践两方面说明中国特色社会主义理论体系形成的条件。','国际上，和平与发展的时代趋势、科技进步和世界开放加深，为中国发展带来机遇，也产生竞争与风险。国内改革开放和现代化建设提出发展道路、体制改革和党的建设等新问题。党在总结国内外经验、处理现实课题的过程中形成和发展理论体系。这既不是只由外部环境自动产生，也不是脱离时代条件的纯粹理论设计。',['mg-resolution-2021']);

topic('mg-system',2,'改革开放与理论体系的开篇','党的十一届三中全会作出转移工作中心和实行改革开放的历史性决策。邓小平理论在新时期实践中形成，成为中国特色社会主义理论体系的开篇之作。',
 ['十一届三中全会开启改革开放和社会主义现代化建设新时期。','解放思想、实事求是推动工作中心转向经济建设。','建设中国特色社会主义成为改革开放以来党的全部理论和实践的重要主题。','邓小平理论是中国特色社会主义理论体系的开篇之作。'],
 '把改革开放解释为放弃社会主义基本制度，或把理论形成简化成先有完整设计再逐条执行。','第五章/2/识记、领会',[
 ['开启改革开放和社会主义现代化建设新时期的标志性会议是','党的十一届三中全会','党的七大','党的八七会议','党的二大','不同会议对应不同历史任务，不可混用。','recall'],
 ['中国特色社会主义理论体系的开篇之作是','邓小平理论','毛泽东思想','科学发展观','“三个代表”重要思想','开篇之作是该理论体系内部历史地位的特定表述。','recall'],
 ['理解改革开放与理论创新的关系，较恰当的是','改革实践提出问题并提供经验，理论总结反过来指导改革','改革只能执行此前全部确定的技术步骤','理论只在改革结束后才有作用','只要改革取得成效就不再需要理论分析','理论与实践形成相互推动的关系。','understand'],
 ],'说明十一届三中全会的转折意义，以及邓小平理论何以成为理论体系的开篇之作。','十一届三中全会推动工作中心转向经济建设、实行改革开放，开启社会主义现代化建设新时期。在这一实践中，邓小平理论围绕什么是社会主义、怎样建设社会主义，回答发展道路、阶段、任务和改革等问题，成功开创中国特色社会主义。因此它是理论体系的开篇之作。其形成同时体现解放思想和总结实践，而不是以放弃基本制度为前提。',['mg-resolution-2021']);

topic('mg-system',3,'理论体系的组成与贯通主题','中国特色社会主义理论体系是发展着的科学理论体系，内部各项成果具有不同重点，也共同服务于坚持和发展中国特色社会主义这一主题。',
 ['体系包括邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想。','各项成果分别回应不同实践阶段的重大问题，不能仅看名称相似。','它们坚持共同的根本立场和思想方法，体现一脉相承又与时俱进。','毛泽东思想是体系形成的重要思想基础，但不列入该体系的内部组成。'],
 '把“体系的思想基础”与“体系的内部组成”混为一谈。','第五章/2/识记、领会、应用',[
 ['下列组合全部属于中国特色社会主义理论体系的是','邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想','毛泽东思想、新三民主义、科学发展观','空想社会主义、邓小平理论、三民主义','毛泽东思想、工农武装割据思想、农业合作化理论','体系范围与整个马克思主义中国化成果的范围不同。','recall'],
 ['改革开放以来贯通党的理论和实践创新的重要主题是','建设和发展中国特色社会主义','恢复半殖民地经济关系','建立不受任何国情约束的统一模式','以技术模仿替代社会制度探索','不同理论成果对同一主题作出阶段性新回答。','recall'],
 ['制作理论关系图时，既标共同思想根基，也标各自时代课题，这种做法体现','从连续性与发展性两方面把握理论体系','认为理论越新就越无需历史基础','把理论发展等同于名称排列','认为共同立场必然取消内容差异','图示既要呈现继承，也要呈现新实践带来的发展。','understand'],
 ],'列出中国特色社会主义理论体系的组成，并说明其共同主题和内部差异。','组成包括邓小平理论、三个代表重要思想、科学发展观和习近平新时代中国特色社会主义思想，共同主题是坚持和发展中国特色社会主义。各项成果坚持共同的基本立场，又分别回应社会主义建设、执政党建设、发展方式以及新时代的一系列重大问题。联系说明它是科学体系，差异说明它在实践中不断发展，不能把共同主题误写为每个结论完全相同。',['mg-theory-relations','mg-resolution-2021']);

topic('mg-system',4,'新时代与新的理论飞跃','中国特色社会主义进入新时代，是我国发展新的历史方位。习近平新时代中国特色社会主义思想在新时代实践中形成发展，系统回答相应时代课题。',
 ['新的历史方位是中国特色社会主义进入新时代，并不意味着社会主义初级阶段已经结束。','相关时代课题包括坚持和发展什么样的中国特色社会主义、怎样坚持和发展，以及建设现代化强国、建设长期执政马克思主义政党等。','习近平新时代中国特色社会主义思想是马克思主义中国化时代化新的飞跃。','应把理论的新发展与中国和世界的变化相联系，避免以单一指标界定时代。'],
 '把进入新时代等同于我国已进入社会主义发达阶段。','第五章/1—2/识记、领会、应用',[
 ['党的十八大以来我国发展新的历史方位是','中国特色社会主义进入新时代','中国已经进入社会主义发达阶段','我国社会主义初级阶段已经结束','中国从此不再存在发展不平衡问题','新时代与初级阶段分别从不同维度描述国情。','recall'],
 ['马克思主义中国化时代化新的飞跃，主要体现于','习近平新时代中国特色社会主义思想','新民主主义革命早期的个别策略','对既有结论只作字词替换','以国外政策文件代替本国理论研究','新的飞跃是对新时代重大理论实践问题的系统回答。','recall'],
 ['某资料用“新时代”证明“已经不必考虑初级阶段实际”。正确辨析是','历史方位变化与基本国情延续可以同时存在','新时代一词本身足以宣布一切发展任务完成','初级阶段只取决于课程教材的出版年份','只要完成某项工程就可以否定全部国情判断','应把时代变化与仍然需要解决的阶段性任务同时把握。','understand'],
 ],'怎样理解进入新时代与社会主义初级阶段之间的关系？','新时代体现中国特色社会主义发展新的历史方位和新的使命任务；社会主义初级阶段则说明我国社会主义发展所处的基本阶段。二者不是相互否定的概念。进入新时代并不意味着发展不平衡不充分等问题消失，更不意味着已经进入发达阶段。理论创新要回应新的条件，同时坚持从基本国情出发。',['mg-resolution-2021']);

topic('mg-deng',1,'首要理论问题、社会主义本质与精髓','邓小平理论围绕什么是社会主义、怎样建设社会主义展开，以解放思想、实事求是为精髓，把发展生产力与共同富裕联系起来认识社会主义本质。',
 ['首要的基本理论问题是什么是社会主义、怎样建设社会主义。','社会主义本质包括解放和发展生产力、消灭剥削、消除两极分化、最终达到共同富裕。','解放思想、实事求是要求摆脱不合实际的观念束缚，按客观规律研究问题。','社会主义本质不能只从生产关系形式判断，也不能把发展生产力与社会目标割裂。'],
 '把解放思想理解为脱离事实任意设想，把共同富裕等同于即时平均分配。','第六章/1/识记、领会、应用',[
 ['邓小平理论首要的基本理论问题是','什么是社会主义、怎样建设社会主义','是否需要进行旧式资产阶级革命','怎样用土地革命代替现代化建设','是否应取消一切商品交换','首要问题贯穿其对道路、阶段、任务和动力的回答。','recall'],
 ['邓小平理论的精髓是','解放思想、实事求是','以阶级斗争为纲','不分析条件地追求速度','把计划数量作为唯一标准','解放思想与实事求是相互联系，创新必须符合实际。','recall'],
 ['某方案只以少数人的财富增长证明“社会主义本质已全面实现”。对此应强调','生产力发展还要同消除两极分化和共同富裕的方向结合','财富总量增长即可替代所有社会目标','共同富裕要求不同岗位收入立即完全相同','社会主义本质只涉及企业名称和登记形式','社会主义本质包含生产力与社会关系、发展目标相联系的内容。','apply'],
 ],'概括社会主义本质理论的内容，并说明它为何不能简化为经济总量增长。','社会主义本质理论将解放和发展生产力，同消灭剥削、消除两极分化、最终达到共同富裕联系起来。发展生产力提供物质基础，但经济总量增长本身不能说明利益分配和社会目标已经实现。因此，既不能忽视生产力，也不能只看少数人的收入或某一年的增长速度。要在发展中推进共同富裕，并按实际条件逐步实现。',['mg-deng-content']);

topic('mg-deng',2,'社会主义初级阶段与基本路线','初级阶段理论同时说明我国已经是社会主义社会和社会主义仍处于初级阶段。基本路线以经济建设为中心，把四项基本原则和改革开放统一起来。',
 ['初级阶段有两层含义：我国已经进入社会主义社会，又仍处于其初级阶段。','基本路线可概括为一个中心、两个基本点，即经济建设、四项基本原则、改革开放。','经济建设是中心，四项基本原则是立国之本，改革开放是强国之路。','不能超越阶段，也不能以初级为由放弃社会主义方向和发展责任。'],
 '将“初级阶段”理解为尚未进入社会主义，或把两个基本点视为只能二选一。','第六章/2/识记、领会、应用',[
 ['社会主义初级阶段理论强调的两层含义是','已是社会主义社会，并仍处于社会主义初级阶段','还不是社会主义，但已经进入发达资本主义','已经完成现代化，因此不再有阶段任务','各地区发展程度相同，因此阶段分析不再必要','制度性质与发展程度是相关而不同的维度。','recall'],
 ['“一个中心、两个基本点”中的中心是','经济建设','对外贸易额','国有企业数量','短期财政结余','中心任务不能被某一部门或某一个统计指标替代。','recall'],
 ['某讨论把坚持四项基本原则与改革开放看成互相排斥。合理分析是','前者提供政治保证，后者提供发展动力，应围绕经济建设相统一','只要实行改革就应取消基本制度','坚持原则意味着不得调整具体体制','两个基本点可以长期脱离中心任务各自运转','基本路线是统一整体，不能割裂其组成部分。','understand'],
 ],'解释初级阶段的两层含义，并说明基本路线三个方面的关系。','我国已经是社会主义社会，必须坚持社会主义；同时仍处于初级阶段，必须从发展不充分的实际出发。基本路线以经济建设为中心，四项基本原则提供政治保证，改革开放提供动力和路径，三者相互联系。不能以坚持原则为由固守不合理体制，也不能以改革为名改变社会主义方向，更不能脱离实际急于求成。',['mg-deng-content']);

topic('mg-deng',3,'根本任务、发展战略与科技教育','发展生产力是社会主义的根本任务。邓小平提出分步骤实现现代化，重视科学技术和教育，使战略目标与现实条件相衔接。',
 ['发展生产力是根本任务，发展是硬道理，科学技术是第一生产力。','原“三步走”战略依次解决温饱、达到小康、到21世纪中叶基本实现现代化；应按提出时的历史口径理解。','科技教育支撑发展，教育要面向现代化、面向世界、面向未来。','发展既要抓住机遇，也要重视条件与质量，不能把台阶式发展解释为脱离规律的突进。'],
 '把历史“三步走”战略与新时代分两步战略的阶段和时间表混写。','第六章/2/识记、领会、应用',[
 ['邓小平关于社会主义根本任务的认识是','发展生产力','只调整已有产品的分配而不再生产','用所有制名称代替经济发展','把阶级斗争作为全部工作的唯一中心','制度优越性需要通过生产力发展和生活改善体现。','recall'],
 ['教育“三个面向”是面向现代化、面向世界和','面向未来','面向现有考试名次','面向单一职业工种','面向短期经济排名','三个面向强调教育的战略视野。','recall'],
 ['讲授原“三步走”战略时，把第二步的小康目标和21世纪中叶现代化目标混为一步。应如何处理？','分别说明温饱、小康、基本现代化的递进关系及历史语境','只按当前年份重新改写历史目标','认为战略步骤不需要同物质条件相联系','用某一城市收入水平替代全国发展战略','学习历史战略应准确区分阶段，不能用现时表述覆盖原有口径。','understand'],
 ],'概述原“三步走”战略的递进思路，并说明科技教育的作用。','原三步走战略从解决温饱，到达到小康，再到21世纪中叶基本实现现代化，体现按条件分阶段推进的思路。科学技术是第一生产力，教育为技术进步与人才成长提供基础，因此现代化不能仅靠增加物质投入。三个面向要求教育关注现代化、世界和未来。复习时应把这一历史战略与后来新时代的战略安排区分开。',['mg-deng-content']);

topic('mg-deng',4,'改革开放、市场经济与三个有利于','改革是社会主义制度的自我完善和发展，开放同独立自主并行。计划与市场是资源配置的经济手段，不能仅凭有无市场判断社会制度性质。',
 ['改革是社会主义制度的自我完善和发展，旨在解放和发展生产力。','计划和市场不等同于社会主义与资本主义的本质界线。','三个有利于标准分别关注社会主义生产力、社会主义国家综合国力和人民生活水平。','开放要吸收有益成果、利用有利条件，同时坚持独立自主。'],
 '把市场机制直接等同于资本主义，把改革误写为否定社会主义基本制度。','第六章/2/识记、领会、应用',[
 ['判断改革和各方面工作是非得失的“三个有利于”不以形式名称为准，而重视','生产力、综合国力与人民生活的实际改善','文件篇幅、项目数量与宣传次数','外来模式采用比例','所有地区是否采用同一种操作流程','三个标准强调实践效果及社会主义方向。','recall'],
 ['邓小平对计划与市场关系的主要突破在于','把计划与市场视为经济手段而非两种制度的本质标签','认为只要有计划就必然是社会主义','认为只要有市场就必须取消公有制','认为两种手段在实践中不能共同使用','经济调节手段同社会基本制度不能简单画等号。','recall'],
 ['一个改革试点提高了效率，但群众生活受损、公共服务明显退步。按三个有利于标准，应当','综合检视生产力、国家能力和群众生活，不能仅凭效率一项定论','只要产值提高就排除其他标准','只看是否使用市场工具便作结论','以试点来自哪个国家作为最终依据','实际评价需要三个方面的综合分析，而非单项指标。','apply'],
 ],'列出三个有利于标准，并说明它们怎样帮助摆脱计划与市场的标签化争论。','三个有利于是有利于发展社会主义社会的生产力、增强社会主义国家的综合国力、提高人民生活水平。它们把评价重点引向方向和实际效果，避免只凭计划或市场的形式判定性质。比如评价流通改革，应看生产与供应效率、公共能力和群众生活是否改善，而不是只看采取了哪种资源配置工具。',['mg-deng-content','mg-theory-relations']);

topic('mg-deng',5,'共同富裕、两个大局与两手抓','共同富裕允许有条件的地区和个人先发展，再带动和帮助后发展者。发展还要求物质文明与精神文明协调，不能以财富积累替代价值与制度建设。',
 ['先富是实现共同富裕的路径探索，不是把两极分化作为最终目标。','两个大局要求先发挥沿海等条件较好地区的优势，再随着发展支持内地，促进区域共同发展。','两手抓、两手都要硬强调物质文明和精神文明建设等方面不能偏废。','共同富裕是逐步实现的共同目标，既反对平均主义，也反对贫富悬殊固化。'],
 '把先富理解为先富者不承担带动帮助责任，或把精神文明当作发展完成后的附属装饰。','第六章/2/识记、领会',[
 ['邓小平允许一部分地区和个人先富起来的最终指向是','共同富裕','把两极分化作为长期固定制度','以平均分配取消所有差别','使后发展地区永远依附先发展地区','先富与共富是路径和目标的联系。','recall'],
 ['“两手抓、两手都要硬”在文明建设中的要求是','物质文明和精神文明建设相互支持、共同推进','先完全停止精神文明建设再发展经济','只重视精神教育而不发展生产','两种建设必须使用完全相同的指标和方法','共同推进不等于具体方法和评价指标完全相同。','recall'],
 ['某沿海地区发展后通过产业协作和教育支持带动内地，最直接体现','两个大局及先富带动后富的思路','以区域封锁保护先发优势','要求所有地区同时达到同一收入数字','把共同富裕限定为某一地区内部问题','区域先后发展应形成带动、支持和共同发展的关系。','apply'],
 ],'说明先富与共富、沿海与内地两个大局的关系。','共同富裕是目标，先富是依据条件差异探索的发展路径。允许条件较好的地区先发展，可以形成经验和物质能力；随着发展，应通过协作和支持带动后发展地区。两个大局体现这一先后相联系的安排。因此，不能把先富解释为地区封锁或差距永久固化，也不能把共同富裕理解为不顾生产条件的平均分配。',['mg-deng-content']);

topic('mg-deng',6,'和平发展、一国两制与党的建设','邓小平理论还涉及国际环境、祖国统一和领导力量。“一国两制”以一个中国为前提，党的建设要适应改革开放和现代化任务。',
 ['和平与发展是时代的两大主题，应为发展争取有利外部环境。','一国两制以一个中国为前提，国家主体坚持社会主义制度，特定地区可依法保持原有资本主义制度。','办好中国的事情关键在党，改革开放需要改善领导、加强制度和纪律建设。','邓小平理论开创中国特色社会主义，为改革开放和现代化建设提供科学指导。'],
 '把一国两制理解为两个主权国家，或以开放为由否定独立自主。','第六章/2—3/识记、领会、应用',[
 ['“一国两制”科学构想的前提是','一个中国','两个独立主权国家','取消国家主体的社会主义制度','所有地区采用完全相同的具体经济制度','一国是前提，两制是统一国家内的制度安排。','recall'],
 ['邓小平理论的历史贡献，最恰当的概括是','成功开创中国特色社会主义','第一次形成新民主主义革命理论','完成全部新时代治理问题的最终回答','把中国发展同世界联系完全隔离','应在改革开放和现代化建设的历史语境中认识其贡献。','recall'],
 ['讨论对外开放时，认为必须由外部力量替中国决定发展道路。合理回应是','开放学习与独立自主相统一，国家道路须立足本国实际自主选择','开放意味着所有制度选择均由外部决定','独立自主要求切断科技教育交流','外部环境对发展没有任何影响','开放利用外部有利条件，不取消自主判断。','understand'],
 ],'解释一国两制的基本前提，并说明改革开放为什么同时需要加强党的建设。','一国两制以一个中国为前提，国家主体坚持社会主义，特定地区依法保持原有资本主义制度，不能理解为两个主权国家。改革开放带来新任务和新考验，需要党提高领导能力，改进方法，加强制度与纪律建设，以保证方向、组织实施和维护人民利益。统一问题、发展问题与领导力量虽属不同方面，却共同服务于中国特色社会主义事业。',['mg-deng-content','mg-resolution-2021']);

topic('mg-represents',1,'三个核心观点及其相互关系','三个代表重要思想要求党代表先进生产力的发展要求、先进文化的前进方向和最广大人民的根本利益。三方面有机统一，不能以其中一方面代替整体。',
 ['先进生产力是物质基础，先进文化提供精神动力和智力支持。','人民群众既是生产力和文化发展的创造主体，也是成果的受益主体。','实现最广大人民的根本利益是出发点和归宿，三方面在实践中统一。','劳动者是推动先进生产力和社会进步的根本力量，科学技术是先进生产力的重要体现。'],
 '把三个代表拆成互不相关的三个工作部门，或仅以经济增长代替群众利益。','第七章/1/识记、领会',[
 ['“三个代表”中的文化要求是始终代表','中国先进文化的前进方向','所有流行文化的商业销量','不分先进落后的全部旧观念','少数人的特殊审美偏好','先进方向与销量、流行程度和私人偏好不能混同。','recall'],
 ['在三个核心观点的联系中，实现最广大人民根本利益是','出发点和归宿','只在生产力停止发展后才考虑的目标','文化发展之外的私人选择','仅由少数群体获得收益即可实现的要求','人民利益同生产力、文化发展相联系。','recall'],
 ['一个发展方案兼顾技术进步、公共文化与群众受益，这一评价思路体现','把三个核心观点作为有机整体把握','认为文化可脱离物质条件独立解决一切问题','认为只要有经济增量就可以排除群众利益','把群众仅当作被动接受者而非实践主体','三方面相互促进，主体地位和成果受益也相联系。','understand'],
 ],'说明三个代表核心观点的相互关系，为什么不能只讲其中一个方面？','先进生产力提供物质基础，先进文化提供精神动力和智力支持，人民群众则既是创造主体，也是发展成果的受益者。三者统一于中国特色社会主义实践，最广大人民的根本利益是出发点和归宿。只讲产值而不顾文化与群众利益，会把发展目标缩窄；脱离物质基础只讲文化，也难以实现人民利益。',['mg-represents-formation']);

topic('mg-represents',2,'发展、市场经济与改革发展稳定','三个代表重要思想把发展作为党执政兴国的第一要务，强调社会主义市场经济体制建设，并把改革动力、发展目标和稳定前提联系起来。',
 ['发展是党执政兴国的第一要务，发展应体现人民利益和全面进步。','我国经济体制改革的目标是建立社会主义市场经济体制。','改革是动力，发展是目的，稳定是前提，应把三者统一起来。','扩大开放坚持引进来与走出去相结合，物质、政治、精神文明协调发展。'],
 '把稳定理解为停止改革，把发展仅等同于短期增长，把市场经济同社会主义方向对立。','第七章/2/识记、领会',[
 ['“三个代表”重要思想强调党执政兴国的第一要务是','发展','以不变应付所有社会变化','只增加组织规模','维持一切旧体制安排','发展关系事业全局和人民利益，不能缩小为组织数量。','recall'],
 ['正确处理改革、发展、稳定关系时，稳定的地位是','前提','替代发展的终极目标','取消改革的永久依据','与群众生活毫无关系的外部条件','稳定为改革发展创造条件，也须通过改革发展巩固。','recall'],
 ['改革方案既设置推进步骤，又安排群众利益保障与风险应对，体现','把改革力度、发展速度和社会可承受程度统一起来','以有风险为由停止所有必要改革','只看短期速度而排除社会影响','把群众需求视为改革方案之外的问题','三者统一需要具体把握节奏和利益关系。','apply'],
 ],'说明改革、发展、稳定的关系，并用改革方案设计作例子。','改革提供动力，发展是目的，稳定是前提。方案设计应把改革力度、发展速度和社会可承受程度结合起来。例如，调整公共服务体制时，既改进效率，也安排过渡服务、听取群众意见并应对风险，避免改革中断基本保障。稳定不是维持所有旧机制不动，发展也不能以忽视群众切身利益为代价。',['mg-theory-relations']);

topic('mg-represents',3,'先进性与党的建设新的伟大工程','三个代表重要思想把党自身建设同中国特色社会主义事业相联系。先进性需要体现在实际理论、路线、组织和工作中，而不是仅靠身份或口号维持。',
 ['贯彻三个代表重要思想，关键在与时俱进，核心在坚持党的先进性，本质在执政为民。','党的建设要提高领导水平和执政水平，提高拒腐防变和抵御风险能力。','巩固党的阶级基础、扩大党的群众基础，应根据社会变化团结建设者。','党员领导干部讲学习、讲政治、讲正气，保持同人民群众的联系。'],
 '把先进性当成取得执政地位后自动永久保持的标签。','第七章/2/识记、领会、应用',[
 ['贯彻“三个代表”重要思想的根本要求，核心在于','坚持党的先进性','用历史资格代替现实表现','把执政时间长短作为唯一尺度','减少同群众的实际联系','先进性要落实于理论、路线和实际工作。','recall'],
 ['党员领导干部“三讲”的内容是','讲学习、讲政治、讲正气','讲速度、讲排名、讲规模','讲资历、讲人情、讲关系','讲项目、讲广告、讲收益','三讲针对党性修养与干部建设，不能以行政业绩指标替代。','recall'],
 ['某支部只以组织成立时间证明先进性，不检查服务群众成效。按相关理论，应改为','把先进性落实到学习、制度执行和维护群众利益的实际表现','保留资历唯一标准并增加宣传次数','只看成员个人收入是否提高','认为先进性与工作和人民利益没有关系','先进性是需要在实践中体现和保持的要求。','apply'],
 ],'说明坚持党的先进性为什么需要同执政为民和提高执政能力相联系。','党的先进性不是永久自动保持的身份标签，要在理论、路线、组织和工作中体现。执政为民规定服务人民的方向，提高执政能力使正确方向能够转化为实际成效，拒腐防变和抵御风险能力又有助于维护党的性质。干部应加强学习、政治责任和正气，以群众利益和实际工作检验自身，而非仅凭历史资历。',['mg-represents-formation','mg-theory-relations']);

topic('mg-represents',4,'时代课题与历史地位','三个代表重要思想进一步回答什么是社会主义、怎样建设社会主义，创造性地回答建设什么样的党、怎样建设党，把执政党建设与事业发展紧密结合。',
 ['形成于世纪之交国内外形势变化、改革开放和党的建设实践。','创造性回答建设什么样的党、怎样建设党的问题。','丰富发展中国特色社会主义理论体系，为加强改进党的建设提供重要指导。','党的十六大将其确立为党的指导思想并写入党章。'],
 '把其理论贡献缩小为经济管理技术，或以为只讨论党员个人修养。','第七章/3/识记、领会、应用',[
 ['“三个代表”重要思想创造性回答的突出问题是','建设什么样的党、怎样建设党','如何完成旧民主主义革命','如何将互助组改为初级社','如何直接用城市起义代替所有革命道路','应区分执政党建设的新课题与革命、改造中的具体问题。','recall'],
 ['将“三个代表”重要思想确立为党的指导思想并写入党章的是','党的十六大','党的七大','党的十五大','党的十八大','不同理论成果确立指导地位的会议要准确区分。','recall'],
 ['评价该理论的历史地位，只说“增加了几项基层管理技巧”，主要不足是','未把握其对执政党建设和中国特色社会主义理论体系的发展意义','过于强调了它对经济、政治、文化等领域的系统联系','把它同所有社会实践联系得过于紧密','错误说明了它完全不涉及组织建设','理论地位应从时代课题、体系发展与实践指导理解。','understand'],
 ],'从时代课题和理论体系发展两个角度说明三个代表重要思想的历史地位。','它在国内外形势和党自身状况发生变化的条件下，进一步研究社会主义建设，创造性回答建设什么样的党、怎样建设党。它把先进生产力、先进文化与人民利益相贯通，把党的建设新的伟大工程同中国特色社会主义事业联系起来，丰富发展了中国特色社会主义理论体系。因此，它的意义不限于基层管理技巧，而涉及执政方向、基础和能力建设。',['mg-represents-formation','mg-resolution-2021']);

topic('mg-development',1,'科学发展观的四项科学内涵','科学发展观第一要义是发展，核心立场是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。四方面相互联系，不是可任意交换的术语。',
 ['第一要义回答发展在全局中的地位，不能用停止发展解决发展问题。','以人为本强调为人民发展、靠人民发展、让人民共享成果并促进人的全面发展。','全面协调可持续关注各领域联系、比例关系与长远条件。','统筹兼顾要求总揽全局又突出重点，处理当前与长远、局部与整体等关系。'],
 '把核心立场、基本要求和根本方法混写；把统筹兼顾解释为平均用力。','第八章/1/识记、领会',[
 ['科学发展观的核心立场是','以人为本','统筹兼顾','全面协调可持续','只重视经济增长速度','核心立场回答为了谁、依靠谁，方法和基本要求另有所指。','recall'],
 ['科学发展观的根本方法是','统筹兼顾','把各领域资源平均分配','只考虑某一部门利益','用短期指标替代长远安排','统筹不等于平均，而是处理全局与重点等关系。','recall'],
 ['一个县研究产业、教育、民生和资源环境的相互影响，再确定重点项目，体现','全面协调可持续与统筹兼顾相联系','只要考虑领域多就无需突出重点','发展只能评价经济总量而不能评价社会影响','统筹兼顾要求所有项目获得同等资金','全面把握关系与抓住重点可以统一。','apply'],
 ],'分别说明科学发展观四项内涵，并解释统筹兼顾为什么不是平均用力。','第一要义是发展，核心立场是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。它们分别说明发展的地位、价值立场、总体要求和工作方法。统筹兼顾要看到各方面联系，协调利益与节奏，又抓住影响全局的重点。例如兼顾教育与产业，不是平均分钱，而是根据实际需求使资源形成相互支持。',['mg-development-content']);

topic('mg-development',2,'转变经济发展方式与城乡协调','科学发展不是单纯追求增长速度，而是提高质量、效益和协调性。转变经济发展方式需要结构调整、科技进步、改善民生和体制改革相联系。',
 ['经济结构战略性调整是加快转变经济发展方式的主攻方向。','科技进步和创新是重要支撑，保障和改善民生是根本出发点和落脚点。','深化改革有助于破除发展方式转变的体制机制障碍。','统筹城乡发展、推进城乡一体化，应改善公共服务与要素流动条件，而非取消一切城乡差别的具体形式。'],
 '把转变发展方式解释为停止增长，或只更换统计指标而不改变资源使用和结构。','第八章/1—2/识记、领会',[
 ['加快转变经济发展方式的主攻方向是','经济结构战略性调整','只扩大高消耗项目数量','把统计表的名称改为新名称','长期以资源浪费换取产量','发展方式转变要求实际结构改变，而非文字替换。','recall'],
 ['加快转变经济发展方式的重要支撑是','科技进步和创新','降低全部公共教育投入','排除产业之间的技术合作','单纯延长劳动时间而忽视效率','科技与创新有助于提高质量和效益。','recall'],
 ['某市产值增长但能耗污染上升、公共服务滞后。依据科学发展观，较合理的改进是','调整产业结构并改善技术、民生和资源环境绩效','仅提高产值目标而不改变发展模式','因为有污染就停止所有发展活动','只修改宣传口径，不改变生产和服务安排','科学发展强调质量、效益和人民生活的综合改善。','apply'],
 ],'说明转变经济发展方式为什么需要把结构、创新和民生结合起来。','结构调整解决发展中产业和需求等方面的比例问题，科技进步与创新提高效率和质量，保障改善民生则体现发展的目的并扩大人的发展条件。还需要改革破除相应体制障碍。例如高耗能地区转型，应推进技术改造、发展适合的产业，并提供就业培训和公共服务，不能只关停项目而不考虑群众生活。',['mg-development-content','mg-development-reader']);

topic('mg-development',3,'人民当家作主与民主政治','社会主义民主政治的本质和核心是人民当家作主。人民代表大会制度是根本政治制度，选举民主和协商民主是相互联系的重要形式。',
 ['人民当家作主体现社会主义民主政治的本质和核心。','人民代表大会制度是我国根本政治制度；不能同政党制度、民族区域自治等具体制度混淆。','坚持党的领导、人民当家作主和依法治国相统一。','选举民主和协商民主各有实现方式，可以相互补充，不是二者只能选一。'],
 '把有了选举解释为不再需要协商，把人民当家作主解释为不受制度程序约束。','第八章/2/识记、领会',[
 ['社会主义民主政治的本质和核心是','人民当家作主','个别部门自主决定全部公共事项','以个人关系代替公共程序','由经济规模直接决定个人政治权利','本质与核心应同具体实现形式区分。','recall'],
 ['我国的根本政治制度是','人民代表大会制度','民族区域自治制度','基层群众自治制度','中国共产党领导的多党合作和政治协商制度','其余属于不同层面的重要制度，不能互换层级。','recall'],
 ['基层讨论认为“进行过选举，就没有必要再就公共方案听取意见”。正确分析是','选举与协商可以相互补充，民主参与不止一个环节','有选举就应禁止群众提出建议','协商可以完全取代所有法定选举','只要意见足够多就可以不遵守法律程序','两种民主形式各有作用，都要在制度和程序中运行。','apply'],
 ],'说明人民当家作主、人民代表大会制度及选举协商的层次关系。','人民当家作主是社会主义民主政治的本质和核心，人民代表大会制度是实现国家权力运行的根本政治制度，选举民主和协商民主则是重要实现形式。它们不能视为同一层次的几个可互换概念。实践中既依法进行选举，也通过协商听取和集中意见，使人民参与贯穿公共事务的相应过程，并坚持党的领导和依法治国。',['mg-development-reader']);

topic('mg-development',4,'文化强国与社会主义核心价值体系','文化建设服务人民、凝聚共同思想基础。社会主义核心价值体系有四方面基本内容，应同后来凝练的社会主义核心价值观准确区分。',
 ['核心价值体系包括马克思主义指导思想、中国特色社会主义共同理想。','还包括以爱国主义为核心的民族精神和以改革创新为核心的时代精神，以及社会主义荣辱观。','文化建设要提高思想道德素质与科学文化素质，满足人民精神文化需要。','文化发展兼顾社会效益与经济效益，不能以商业销量替代价值判断。'],
 '在回答核心价值体系四方面时，只写24字核心价值观，漏掉体系结构。','第八章/2/识记、领会',[
 ['社会主义核心价值体系的灵魂是','马克思主义指导思想','商品销售增长率','个人消费偏好','单一艺术风格','体系各方面各有地位，不能用市场指标替代指导思想。','recall'],
 ['社会主义核心价值体系中的共同理想是','中国特色社会主义共同理想','每个人具体职业目标完全相同','所有地区文化样式完全一致','短期商业利润最大化','共同理想与个人具体志向、文化形式并非同义。','recall'],
 ['文化项目只以流量排名决定价值，忽视内容和群众精神需求。合理改进是','把社会效益和人民需要纳入评价，并兼顾经济效益','只要销量高就无需分析内容影响','只要有社会价值就不需要考虑资源与实施条件','用一种固定文化形式取消所有创作差异','先进文化发展既有价值方向，也要考虑可持续实现。','apply'],
 ],'列出社会主义核心价值体系的基本内容，并说明它与文化建设的联系。','四方面是马克思主义指导思想、中国特色社会主义共同理想、以爱国主义为核心的民族精神和以改革创新为核心的时代精神，以及社会主义荣辱观。它们为文化建设提供方向、理想、精神动力和行为评价。文化项目应提高人的思想道德和科学文化素质、满足精神需要，不能只用流量或利润判定价值，也不能把体系题简化为只写24字核心价值观。',['mg-development-reader']);

topic('mg-development',5,'和谐社会、民生与生态文明','社会和谐与发展相互支持，民生是人民利益的现实体现。生态文明把资源环境条件纳入现代化发展，强调人与自然相协调。',
 ['社会主义和谐社会要求民主法治、公平正义、诚信友爱、充满活力、安定有序、人与自然和谐相处。','社会和谐是中国特色社会主义的本质属性，但不等于没有差异和矛盾。','保障和改善民生应在发展中持续推进，使成果惠及人民。','生态文明坚持节约资源和保护环境的基本国策，重视节约优先、保护优先和自然恢复。'],
 '把和谐等同于没有不同意见，把生态保护当成发展完成以后才考虑的问题。','第八章/2/识记、领会',[
 ['构建社会主义和谐社会的总要求中，与社会公平秩序直接相关的一组是','民主法治、公平正义','只扩大产量、只降低成本','放弃程序、只求一致','封闭管理、排除全部社会参与','和谐社会总要求包含政治、社会、活力、秩序与人与自然关系。','recall'],
 ['建设生态文明所坚持的基本国策是','节约资源和保护环境','先耗尽资源再恢复环境','以污染换增长作为长期方向','把环境保护限定为私人自愿行为','资源和环境是长期发展条件，不是发展之外的附属事项。','recall'],
 ['某地以“保持和谐”为由拒绝居民反映污染问题。按科学发展观，应当','依法听取并解决合理诉求，把民生、环境与发展统筹起来','认为任何不同意见都破坏和谐','以经济产值为由排除生态和生活影响','只要求居民沉默而不调查污染事实','和谐不是没有矛盾，而是妥善协调关系、解决问题。','apply'],
 ],'说明和谐社会、改善民生与生态文明之间的联系，并举一项措施。','和谐社会重视公平、活力、秩序和人与自然关系。民生是群众利益的直接体现，良好环境也是生活与长远发展的条件，三者不能割裂。比如治理河流污染，应调查污染来源、依法推动治理、听取居民意见，同时帮助相关劳动者进行技能转型。既解决环境和健康问题，也兼顾就业与发展，不以压制诉求代替社会协调。',['mg-development-reader','mg-theory-relations']);

topic('mg-development',6,'党的建设、精神实质与历史地位','科学发展观把发展要求同提高党的执政能力相联系，是中国特色社会主义理论体系的接续发展。其精神实质强调解放思想、实事求是、与时俱进和求真务实。',
 ['科学发展观围绕新形势下实现什么样的发展、怎样发展作出回答。','精神实质是解放思想、实事求是、与时俱进、求真务实。','党的建设要提高执政能力，保持先进性纯洁性，增强服务和组织科学发展的本领。','科学发展观丰富发展中国特色社会主义理论体系，党的十八大将其确立为党的指导思想。'],
 '把科学发展观只看作某项环保措施，或认为它不涉及政治、文化和党的建设。','第八章/2—3/识记、领会、应用',[
 ['科学发展观最鲜明的精神实质包括','解放思想、实事求是、与时俱进、求真务实','只追求速度、回避实际效果','固定模式、拒绝反馈','将主观愿望置于客观规律之上','四方面共同体现实事求是和创新发展的要求。','recall'],
 ['将科学发展观确立为党的指导思想的会议是','党的十八大','党的七大','党的十五大','党的十六大','要同2007年十七大把科学发展观写入党章等相关节点区分。','recall'],
 ['干部考核只看建设项目数量，不考察群众受益和资源浪费。改进考核应当','综合评价发展质量、群众利益和长期条件，并提高实际履职能力','继续只按工程数量排名','以是否提出口号代替所有成效分析','认为党建与推动科学发展没有联系','科学发展要求正确政绩观，并以能力和作风保证落实。','apply'],
 ],'概述科学发展观的精神实质和历史地位，并说明其对党的建设的要求。','其精神实质是解放思想、实事求是、与时俱进、求真务实。它围绕发展问题丰富发展了中国特色社会主义理论体系，对经济、政治、文化、社会、生态和党的建设提供指导。贯彻这些要求，需要党提高执政能力，保持先进性纯洁性，以人民利益和发展实效检验工作。只重项目数量而回避质量和民生，不符合科学发展的实践要求。',['mg-development-content','mg-resolution-2021']);

topic('mg-ending',1,'科学性：按规律认识问题','马克思主义的科学性体现在从客观实际出发，揭示自然、社会和思维发展的规律。科学态度要求分析条件和证据，不以主观愿望代替实际。',
 ['科学性强调认识事物的客观联系和规律。','研究社会问题要分析具体历史条件，不把个别经验无限推广。','科学理论的运用需要事实、逻辑和实践相结合。'],
 '把科学性理解为只要引用理论名称，就无需调查或检验。','结束语/理论特质/识记',[
 ['马克思主义的科学性主要体现为','揭示客观规律并以实际研究为基础','把个人愿望直接作为事实','只依赖语言表述的感染力','只按权威引用的次数判断结论','科学性涉及理论与客观世界的关系。','recall'],
 ['分析某项社会政策能否推广，最符合科学态度的是','比较条件、作用机制和实际效果','只看政策名称是否新颖','以某一成功个案证明所有地区都必然成功','先确定愿望，再排除不利证据','具体分析避免以个别代替一般。','understand'],
 ['调研发现方案与实际情况不符，符合科学性要求的处理是','核实资料并修正判断，继续研究真实原因','删除不符合预期的数据以保留原结论','将调查失败解释为理论不需要事实','只增加报告篇幅而不改变分析','重视事实与修正认识是科学态度的表现。','apply'],
 ],'说明马克思主义科学性的含义，以及它对调查研究的要求。','科学性意味着按照客观事实和规律解释世界。调查中既要核实资料来源，也要分析条件、联系和作用机制，不能把期待中的结果当成实际结果。若发现事实与原有判断不一致，应核查并修正认识，而不是删去不利数据。理论提供分析方向，具体结论仍需要充分研究支持。',['mg-marxism-qualities']);

topic('mg-ending',2,'人民性：为了人民与依靠人民','人民性体现马克思主义为人的解放而奋斗的价值立场。把人民作为历史主体，既关注人民利益，也尊重人民创造实践的作用。',
 ['人民性指向人民解放和人的发展，不以少数人的特殊利益取代人民利益。','人民群众是历史实践的主体，应尊重群众首创精神。','为了人民和依靠人民相统一，不能只把人民当被动接受者。'],
 '把人民性缩小为口号，或认为征求意见就是无原则接受每项个人要求。','结束语/理论特质/识记',[
 ['马克思主义人民性的基本立场是','为人民解放和人的发展而奋斗','只维护少数人的特殊利益','把人民看作与历史无关的旁观者','以个人财富高低决定社会价值','人民性兼具价值方向与历史主体认识。','recall'],
 ['“为了人民”和“依靠人民”的关系是','价值目标与实践主体相统一','前者成立就无需群众参与','二者只适用于互不相关的领域','群众参与可以代替对所有事实和规律的分析','服务对象与实践主体不能割裂。','understand'],
 ['设计社区养老项目时，只有专家讨论而未了解老人需求。体现人民性的改进是','让服务对象参与需求调查和方案反馈，尊重实际合理需要','只在项目名称中增加“为民”字样','用一次宣传活动替代持续服务','把任何个人要求都视为无需分析的最终方案','群众参与和合理需求分析需要落到具体过程。','apply'],
 ],'说明人民性如何同时体现“为了谁”和“依靠谁”，并举例。','人民性要求为人民解放和发展服务，也承认人民群众是创造历史的主体。例如改善社区养老，既要以老人实际生活改善为目标，也要听取老人、家属和工作人员的经验，形成方案后再接受反馈。只宣称为人民却不让群众参与，或不作分析地照办任何个别要求，都不能充分体现这一立场。',['mg-marxism-qualities']);

topic('mg-ending',3,'实践性：认识世界与改造世界','马克思主义不是只解释世界的书斋学说，而是指向社会实践的理论。实践提出问题，也检验、丰富和发展理论认识。',
 ['实践是理论形成发展的重要基础，也是检验认识的标准。','理论通过指导实践转化为改变现实的力量。','实践检验需要联系条件和过程，不能把一次偶然结果当作全部结论。'],
 '把实践性理解为无需理论的试错，或把理论学习理解为背完即结束。','结束语/理论特质/识记',[
 ['马克思主义的实践性强调','理论联系改造世界的现实活动并接受实践检验','理论只用于解释术语而不用于现实问题','只要行动就不需要任何理论分析','任何一次行动结果都能代替长期研究','实践性不排斥理论，也不允许用偶然经验替代分析。','recall'],
 ['实践与理论认识的关系是','实践提出问题、检验认识，理论指导实践','理论形成后不再与实践发生联系','实践只能执行结论，不能提供新经验','两者之间只有时间先后而无相互作用','理解双向关系有助于避免教条和盲目行动。','understand'],
 ['项目试点未达预期，团队根据反馈查找条件差异并调整措施，体现','在实践检验中修正和发展认识','把实践当作对理论名称的装饰','宣布所有理论均无实际意义','用一次失败直接证明全部目标不可能','调查、分析与调整体现理论实践相互促进。','apply'],
 ],'说明理论与实践的关系，并解释为什么“多行动、不分析”不等于重视实践。','实践为认识提供问题、经验和检验，理论则帮助把握规律、指导行动。重视实践不仅是增加行动次数，还要调查条件、分析过程、总结结果。缺乏分析的重复试错可能把同样错误不断放大。比如试点效果不佳，应研究服务对象、资源与执行条件，再调整方案，把经验提升为可说明原因的认识。',['mg-marxism-qualities']);

topic('mg-ending',4,'开放性：坚持与发展相统一','马克思主义是不断发展的开放理论。开放不是放弃基本立场，而是在新条件中吸收有益成果、回应新课题，保持理论创造力。',
 ['开放性要求面对时代和实践的新问题继续丰富发展理论。','坚持基本立场、观点、方法，同探索新的具体认识可以统一。','学习人类有益文明成果应作分析选择，不是照单全收。'],
 '把坚持解释为每项具体结论永远不变，把发展解释为取消全部基本原则。','结束语/理论特质/识记',[
 ['马克思主义理论的开放性主要是指','能够在新的实践和时代条件中不断丰富发展','可以随意放弃人民立场','所有外来观点都不加分析地采用','形成之后的具体表述不再允许讨论','开放性同科学性、人民性和实践性相统一。','recall'],
 ['以科学态度对待马克思主义，应如何理解坚持和发展？','坚持基本立场方法，在新实践中发展具体认识','坚持意味着拒绝研究所有新问题','发展意味着理论与已有基础完全无关','二者只能在不同课程中各选其一','基本原则与具体认识的发展不能简单对立。','understand'],
 ['面对人工智能带来的劳动变化，符合开放性要求的研究是','运用基本立场方法调查新劳动形态，吸收有益研究并形成新认识','只因经典未使用同样术语就拒绝研究','用技术流行程度替代社会影响分析','认为研究新技术必须先否认人民利益和实践检验','开放理论能回应新现实，仍须保持科学和人民立场。','apply'],
 ],'为什么不断发展的开放性不等于任意改变基本立场？','开放性是随着实践和时代变化拓展认识，并不是取消科学分析、人民立场和实践检验。比如研究人工智能劳动，应调查劳动过程、技术作用和利益关系，吸收有益知识，再形成适合新情况的判断。既不能因为经典没有同样术语就拒绝研究，也不能因技术新颖而不顾人民利益。坚持基本立场与发展具体认识正是在这一过程中统一。',['mg-marxism-qualities']);

const chapterTopicIds=id=>topics.filter(t=>t.chapterId===id).map(t=>t.id);
for(const t of topics){
  if(t.chapterId==='mg-exploration')t.sourceIds.push('mg-exploration-history');
  if(t.id==='mg-exploration-03')t.sourceIds.push('mg-chenyun-exploration');
  if(t.chapterId==='mg-ending')t.level='recall';
}
material('mg-intro',chapterTopicIds('mg-intro'),
 '材料：两个学习小组研究乡村公共服务。甲组只寻找经典著作中的相似句子，不调查本地情况；乙组认为问题很新，应该完全抛开基本理论。另有同学提出，应调查人口、交通和群众需求，也研究本地互助文化，再分析适合的服务方案。\n问题：（1）结合中国化时代化的要求评价前两种思路。（2）说明后一建议如何体现两个结合。（3）解释理论继承与创新的关系。',
 ['甲组把理论当现成答案，乙组切断基本立场方法，两者都割裂理论与实践。','调查国情和现实需要体现第一个结合；辨析互助文化合理内容并作转化体现第二个结合。','结合应形成能解释和解决问题的新认识，而不是引语与材料的简单拼接。','继承基本立场方法与回应新任务相统一，体现一脉相承又与时俱进。'],
 '甲组缺乏实际调查，把一般原理当作现成技术方案；乙组则把新问题当成放弃基本理论的理由。两者都割裂了理论与实践。后一建议从本地人口、交通和需求出发，体现同中国具体实际相结合；吸收互助文化中的合理内容并根据现代服务要求加以转化，体现同中华优秀传统文化相结合。还应试点、反馈和修正，形成适合本地的新认识。创新因此不是抛弃根基，继承也不是重复原话，而是以基本立场方法研究新实践。');

material('mg-mao',chapterTopicIds('mg-mao'),
 '材料：某展览介绍毛泽东思想，列出了革命、军队、文化和党的建设等内容，但没有解释各部分如何联系。学生小组准备增加一个公共服务调研项目：入户听意见、核对客观条件、借鉴其他地区经验后自主设计方案，并在实施后回访。有同学认为，这些方法只适用于革命时期。\n问题：（1）说明毛泽东思想作为科学体系的含义。（2）指出调研中的活的灵魂三个方面。（3）结合历史地位评价“只适用于革命时期”的说法。',
 ['科学体系涵盖多个领域，并由共同立场观点方法贯通，不是零散口号。','入户并集中意见、回到实践反馈体现群众路线；核对条件体现实事求是。','自主设计同时吸收有益经验体现独立自主，并非拒绝借鉴。','毛泽东思想是第一个重大理论成果与革命建设指南，其科学方法具有长期价值；具体政策须联系历史条件。'],
 '展览应把六方面主要内容同共同的立场观点方法联系起来，说明其体系性。项目中，听取群众意见并回访检验体现群众路线，核对条件和实施效果体现实事求是，结合实际自主设计而又借鉴经验体现独立自主。毛泽东思想实现第一次历史性飞跃，指导革命和建设，其科学方法仍有重要价值。但这不等于当年每项具体政策都可直接照搬今天，应继承科学原则，结合新的实践继续发展。');

material('mg-revolution',chapterTopicIds('mg-revolution'),
 '材料：历史学习小组讨论土地革命战争时期的道路选择。当时敌人的主要力量集中于大城市，广大农村农民有强烈土地要求，各地政治经济发展又很不平衡。小组发现，建立根据地既要组织武装保护，也要开展土地与群众工作，还要处理联合不同力量的问题。\n问题：（1）从国情解释农村道路的选择。（2）分析土地革命、武装斗争与根据地的关系。（3）说明三大法宝为什么需要相互配合，并区分革命的当前性质与前途。',
 ['道路来自半殖民地半封建国情、敌我力量分布和农村群众条件，不是普遍地理规律。','土地革命是基本内容，武装斗争是主要形式，根据地是战略阵地。','统一战线团结力量，武装斗争开展革命，党的建设保证领导和正确运用两种武器。','革命由无产阶级领导，当时性质为新式资产阶级民主主义革命，前途是社会主义。'],
 '材料显示大城市敌强我弱，而农村具有土地要求和发展不平衡所提供的空间，因此道路选择必须根据中国具体条件。土地革命动员农民，武装斗争提供保护和主要斗争形式，根据地组织政权、生产与群众工作，三者相互依存。统一战线扩大力量，武装斗争推进革命，党的建设保证正确领导和策略运用，不能互相替代。革命当前是反帝反封建反官僚资本主义的民主主义革命，但由无产阶级领导并指向社会主义，不能因此提前混同两个阶段的全部任务。');

material('mg-transition',chapterTopicIds('mg-transition'),
 '材料：某博物馆把20世纪50年代的几组史料并列：国家发展工业，小农由互助组织逐步走向合作社，手工业者采用适合行业的合作形式，部分私营企业经过加工订货、公私合营等形式改变经营与所有制关系。讲解员准备把这些简单归结为“组织名称变化”。\n问题：（1）用一化三改说明史料的整体联系。（2）分析合作化与和平赎买的不同对象和过渡方式。（3）说明三大改造基本完成的制度意义，并提出评价时应注意的教训。',
 ['一化是工业化，三改对象为农业、手工业和资本主义工商业，建设与改造相互促进。','农业手工业通过合作逐步组织小生产者；资本主义工商业通过国家资本主义与和平赎买改变所有制。','1956年底改造基本完成，社会主义基本制度确立，不只是名称变化。','改造应结合生产发展、群众自愿、人员安排，分析后期过快、形式单一等不足。'],
 '工业建设和三方面改造构成一化三改，体现发展生产力与调整生产关系相互促进。农业和手工业主要面对分散的小生产者，采取由低级到高级的合作形式；资本主义工商业则经国家资本主义过渡形式实行和平赎买。1956年底改造基本完成，社会主义基本制度确立，因此变化涉及经济关系和社会制度，而非仅换名称。同时，评价要研究生产是否发展、群众意愿与人员安排是否受到尊重，并总结推进过快、形式过于单一等问题。');

material('mg-exploration',chapterTopicIds('mg-exploration'),
 '材料：一份关于初步建设探索的学习记录写道：“重工业投入增长很快，但有些时期农业、轻工业和群众生活未得到相应兼顾；讨论建设比例时，部分善意批评被当作敌对意见。与此同时，长期建设形成的工业设备、技术队伍和经验又为后来的改革提供了重要条件。”\n问题：（1）从工业化关系与社会矛盾理论分析前两种问题。（2）概括初步探索的意义。（3）说明评价成就与曲折应采用的态度。',
 ['重工业发展要联系农轻重比例、积累消费和群众生活，不可脱离经济规律。','善意批评应按人民内部矛盾采用民主方法，不能一概敌我定性。','工业与国民经济基础、技术队伍和经验为后来提供物质基础、理论准备及宝贵经验。','全面具体评价，不以成就掩盖失误，也不以失误否定全部成果。'],
 '前一问题反映农轻重比例及积累与消费关系处理不当。农业、轻工业关系原料、市场和生活条件，工业化不能只看重工业投资。把善意意见敌对化则混淆两类矛盾，应以民主讨论、批评等方法处理人民内部问题。材料中的设备、队伍和经验说明探索为后来提供物质基础、理论准备和宝贵经验。总结既要看到这一历史贡献，也要研究失误产生的条件，继承基础、改进体制和方法，避免全盘肯定或全盘否定。');

material('mg-system',chapterTopicIds('mg-system'),
 '材料：小组制作理论发展时间轴，依次标出改革开放、三个代表重要思想、科学发展观和新时代的新发展。一名同学建议把早期成果全部删去，理由是“有了新理论，旧理论就没有基础作用”；另一名同学把进入新时代写为“初级阶段已经结束”。\n问题：（1）说明理论体系的组成和开篇之作。（2）评价两项建议。（3）说明理论发展同社会历史条件的联系。',
 ['理论体系的四项组成与邓小平理论的开篇地位。','新成果同既有成果一脉相承又与时俱进，不应删除思想和实践基础。','新时代是新的历史方位，不意味着初级阶段结束。','和平发展、世界开放、中国实践与党自身课题共同推动理论创新。'],
 '体系包括邓小平理论、三个代表重要思想、科学发展观和习近平新时代中国特色社会主义思想，邓小平理论是开篇之作。新的成果坚持共同根基，又回答新的时代问题，因此不能以新代旧的名义删去继承关系。进入新时代也不等于初级阶段结束，历史方位和发展阶段是相关而不同的判断。时间轴应补充时代条件、改革实践和党自身面临的问题，让学习者理解每项成果为何形成、解决什么问题，而非只排列名称。');

material('mg-deng',chapterTopicIds('mg-deng'),
 '材料：一份模拟历史讨论记录呈现改革开放中的三个争议：有人因企业运用市场手段就判定其背离社会主义；有人只以少数人迅速致富认定发展目标已经实现；也有人要求沿海取得发展后同内地加强合作，并同时推进教育和精神文明。\n问题：（1）用计划市场关系和三个有利于标准分析第一项争议。（2）用社会主义本质和先富共富关系分析第二项争议。（3）解释第三项主张所体现的两个大局和两手抓思想。',
 ['计划市场是经济手段，评价须综合生产力、综合国力和人民生活。','社会主义本质把生产力发展同消除两极分化、最终共同富裕联系。','先富是路径，带动帮助后富并逐步共同发展才体现目标。','两个大局体现沿海先发展再支持内地；两手抓要求物质精神文明不偏废。'],
 '不能仅凭使用市场工具判断制度性质，计划与市场都是经济手段，应看是否有利于社会主义生产力、综合国力和人民生活。少数人致富也不足以证明全部发展目标实现，社会主义本质还要求消除两极分化并最终共同富裕。先富应带动和帮助后富。沿海发展后支持内地体现两个大局的联系；同时推进教育和精神文明则体现两手抓，使物质发展与人的素质、价值和社会风尚相互支持。');

material('mg-represents',chapterTopicIds('mg-represents'),
 '材料：某地研究一个转型方案，提出技术改造和文化服务项目，却准备取消群众需求调查，认为产值提高后群众利益就自然得到保证。干部学习会上又有人提出，只要维持现状就可以保持稳定，无需考虑改革；还有人只以任职年限证明工作的先进性。\n问题：（1）从三个核心观点的联系评价取消调查。（2）说明改革发展稳定的关系。（3）从先进性和执政为民提出改进方向。',
 ['生产力、先进文化和人民利益是整体，不能以产值自动替代群众利益。','改革是动力，发展是目的，稳定是前提，不能以稳定否定必要改革。','先进性落实于理论路线和工作成效，不以资历自动证明。','应调查需求、安排利益保障，提高领导与服务能力，接受实践和群众评价。'],
 '三个核心观点要求技术进步、文化方向和群众利益相统一。群众还是创造主体，取消需求调查会切断发展与人民的联系。稳定为改革发展提供前提，但应通过改革发展不断巩固，不能等同于冻结现状。先进性也不能仅以任职年限证明，应体现在正确决策、服务群众和实际成效中。方案应恢复调查，说明群众如何受益，安排过渡保障与风险应对，同时加强学习、制度执行和履职能力。');

material('mg-development',chapterTopicIds('mg-development'),
 '材料：在一项关于2010年前后地方发展的模拟案例中，某县工业产值快速增加，但能耗和污染上升，乡村学校、公共卫生服务相对薄弱。县里拟把污染投诉当作“破坏和谐”，并把全部资源继续用于扩大原有产能。\n问题：（1）用科学发展观四项内涵分析问题。（2）提出经济、民生与生态相联系的改进措施。（3）说明人民当家作主与和谐社会建设对处理投诉的要求。',
 ['发展是第一要义，但不能缩小为产值；以人为本、全面协调可持续和统筹兼顾要求综合评价。','调整经济结构和技术，改善教育卫生，节约资源保护环境。','投诉不等于敌对，应核实事实、依法听取意见并回应合理需要。','把人民参与、公平正义、社会活力与生态条件联系，不以压制意见实现表面一致。'],
 '案例的问题不在于发展本身，而是把发展缩小为产值。以人为本要求关注健康、教育和生活，全面协调可持续要求兼顾城乡、社会与生态，统筹兼顾要求抓住结构问题并合理配置资源。可推进节能技术和产业调整，补齐乡村教育卫生短板，治理污染并安排就业支持。居民投诉应核实、依法回应，发挥民主参与作用。和谐是通过民主法治和公平协调关系，不是以拒绝意见掩盖问题。');

material('mg-ending',chapterTopicIds('mg-ending'),
 '材料：小组研究人工智能对劳动的影响。起初有人因经典著作未直接出现相关术语，就否定研究价值；调查后又有人删去与预期不同的访谈，只保留对技术乐观的意见。另一组则访谈不同岗位劳动者，分析事实和利益关系，试行改进建议后继续跟踪反馈。\n问题：（1）用四种理论特质评价上述做法。（2）提出体现这些特质的研究步骤。（3）说明坚持和发展理论如何统一。',
 ['科学性要求尊重事实规律，不能删除不利材料；人民性要求关注劳动者处境与主体作用。','实践性要求进入真实活动、检验并改进认识。','开放性要求研究新问题、吸收有益知识，不因术语未出现而拒绝研究。','调查核验—理论分析—形成建议—试点反馈—修正认识，体现坚持基本立场与发展具体认识。'],
 '按科学性要求，应保留并核实不同证据，不能用预期筛选事实；人民性要求了解不同岗位劳动者的需要与作用；实践性要求把方案用于实际并追踪效果；开放性要求研究人工智能带来的新问题。小组可先明确问题与对象，调查技术使用、劳动条件和利益变化，运用理论分析后形成建议，再试点反馈和修正。基本立场方法是研究根基，对新现实形成的新判断则是发展，二者通过实际研究统一起来。');

// 固定种子的均衡位置排列，避免顺序练习出现循环答案；不依赖运行时随机。
const singles=questions.filter(q=>q.type==='single');
const answerPositions=singles.map((_,index)=>index%4);
let seed=150412024;
for(let index=answerPositions.length-1;index>0;index--){
  seed=(Math.imul(seed,1664525)+1013904223)>>>0;
  const other=seed%(index+1);
  [answerPositions[index],answerPositions[other]]=[answerPositions[other],answerPositions[index]];
}
singles.forEach((q,index)=>{const correct=q.options.shift();q.answer=answerPositions[index];q.options.splice(q.answer,0,correct);});
